const $ = s => document.querySelector(s);
const hosted = document.documentElement.dataset.rankmeHosted === 'true';
const pendingCommands = new Map();
if(hosted){$('#workspace-mode-label').textContent='CLOUD';$('#workspace-storage-label').textContent='Synced from your Mac';$('#workspace-footer-label').textContent='Private cloud workspace';}
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL = value => { try { const u = new URL(value); return ['http:','https:'].includes(u.protocol) ? u.href : '#'; } catch { return '#'; } };
const date = v => v ? new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : 'Not scheduled';
const time = v => v ? new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : '—';
const label = s => {const text=s==='needs_confirmation'?'Review business profile':String(s || 'new').replaceAll('_',' ');return text.charAt(0).toUpperCase()+text.slice(1);};
const emptyState = () => ({clients:[],articles:[],jobs:[],events:[],settings:{},status:{}});
let state=emptyState(), view='overview', selected=null, fetching=false, lastState='', toastTimer, activeArticleDialog=null, clientTab='content';
let authenticated=false, pollTimer=null, sessionEpoch=0, credentialRows=[], credentialsLoaded=false, credentialsLoading=false, lastTouch=0;
const client = id => state.clients.find(c=>c.id===id);
const articlesFor = id => state.articles.filter(a=>a.client_id===id);
function badge(status){const cls=['active','ready','published','completed','authenticated','implemented','connected','measured','tracked','improved'].includes(status)?'success':['held','error','failed','declined'].includes(status)?'danger':['new','planned','paused','exported','out_of_scope','off','dismissed','superseded','refreshed','open'].includes(status)?'neutral':'warning';return `<span class="badge ${cls}">${esc(label(status))}</span>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
async function api(path,method='GET',body){if(!authenticated)throw Error('Unlock the workspace first.');const signature=method+' '+path+' '+JSON.stringify(body??{});if(hosted&&method!=='GET'&&[...pendingCommands.values()].some(item=>item.signature===signature)){const pending=Error('This request is already queued. Waiting for your Mac to apply it.');pending.queued=true;throw pending;}const headers=method==='GET'?{}:{'Content-Type':'application/json','X-RankMe-CSRF':RankMeAuth.csrf};if(hosted&&method!=='GET')headers['Idempotency-Key']=crypto.randomUUID();const response=await fetch(path,{method,credentials:'same-origin',headers,...(body!==undefined?{body:JSON.stringify(body)}:{})});if(response.status===401){await RankMeAuth.lock('Your session expired. Unlock the workspace again.',true);throw Error('Session expired.');}let data;try{data=await response.json();}catch{throw Error(`Server returned ${response.status}.`);}if(!response.ok)throw Error(data.error||'Request failed.');if(hosted&&response.status===202&&data.id){pendingCommands.set(data.id,{path,signature,created:Date.now()});for(let attempt=0;attempt<4;attempt++){await new Promise(resolve=>setTimeout(resolve,750));const command=await commandStatus(data.id);if(command?.status==='succeeded'){pendingCommands.delete(data.id);lastState='';return command.result?.data||{};}if(command?.status==='failed'||command?.status==='needs_review'){pendingCommands.delete(data.id);lastState='';throw Error(command.result?.error||command.result?.message||'The Mac could not complete this action. Review it locally.');}}render();const pending=Error('Your request is queued. Waiting for your Mac to connect and apply it.');pending.queued=true;throw pending;}return data;}
async function commandStatus(id){const response=await fetch('/api/commands/'+encodeURIComponent(id),{credentials:'same-origin'});if(response.status===401){await RankMeAuth.lock('Your session expired. Unlock the workspace again.',true);return null;}if(!response.ok)return null;return response.json();}
async function checkPending(){if(!hosted||!authenticated||!pendingCommands.size)return;for(const [id] of [...pendingCommands]){try{const command=await commandStatus(id);if(!command)continue;if(['succeeded','failed','needs_review'].includes(command.status)){pendingCommands.delete(id);lastState='';toast(command.status==='succeeded'?'Your queued change was applied by your Mac.':command.result?.error||command.result?.message||'Your Mac could not complete a queued change.');}}catch{/* Keep the pending action visible while connectivity recovers. */}}}
function cloudStatus(){if(!hosted)return '';const bridge=state.bridge||{},pending=Math.max(Number(bridge.pendingCommands)||0,pendingCommands.size);const online=bridge.online;return `<div class="notice ${online?'':'warning'}" role="status"><strong>${online?'Mac connected':'Waiting for your Mac'}</strong> · ${online?'Changes are processed by your Mac.':'Open RankMe on your Mac to process queued work.'}${pending?` <strong>${pending} pending ${pending===1?'change':'changes'}.</strong>`:''}${bridge.lastSeen?` <span class="hint">Last contact: ${esc(time(bridge.lastSeen))}</span>`:''}</div>`;}

async function refresh(force=false){if(fetching||!authenticated)return;fetching=true;const epoch=sessionEpoch;try{const next=await api('/api/state');if(!authenticated||epoch!==sessionEpoch)return;if(hosted)await checkPending();if(!authenticated||epoch!==sessionEpoch)return;const serial=JSON.stringify(next);state=next;if(force||serial!==lastState){lastState=serial;const focused=document.activeElement;const editing=focused&&['INPUT','TEXTAREA','SELECT'].includes(focused.tagName);if(!editing){const scroll=window.scrollY;render();window.scrollTo({top:scroll,behavior:'instant'});}if(activeArticleDialog&&$('#modal').open&&activeArticleDialog.tab!=='edit'){const article=state.articles.find(a=>a.id===activeArticleDialog.id);if(article&&JSON.stringify(article)!==activeArticleDialog.snapshot){const modalScroll=$('#modal').scrollTop;articleModal(activeArticleDialog.id,activeArticleDialog.tab);$('#modal').scrollTop=modalScroll;}}}$('#last-sync').textContent=(hosted?(state.bridge?.online?'Mac connected':'Waiting for Mac'):'Connected locally')+' · '+new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});}catch(e){if(!authenticated||epoch!==sessionEpoch)return;if(!lastState)$('#page').innerHTML=`<div class="card empty"><h2>Workspace unavailable</h2><p>${esc(e.message)}</p><button class="button" data-action="refresh">Try again</button></div>`;$('#last-sync').textContent='Connection interrupted. Retrying…';}finally{fetching=false;}}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><span class="eyebrow">CONTENT OPERATIONS</span><h1>${esc(title)}</h1><p class="subheading">${esc(desc)}</p></div>${actions}</div>`;}
function health(){const s=state.status||{},okay=s.available&&s.authenticated;return `<div class="card status-card"><div class="card-head"><h3>AI connection</h3>${badge(okay?'authenticated':s.available?'needs_sign_in':'not_connected')}</div><p>${esc(s.message||(okay?'Codex is connected. Your subscription powers this workspace.':'Connect Codex to start researching and writing.'))}</p><div class="muted">${esc(s.version||'ChatGPT subscription · no API key')}</div>${view==='settings'?'':'<button class="button small section" data-nav="settings">Connection settings</button>'}</div>`;}
function eventRows(events){return events.length?events.map(e=>`<div class="event"><span class="event-dot ${esc(e.level)}"></span><div><p>${esc(e.message)}</p><small>${esc(client(e.client_id)?.name||'Workspace')} · ${time(e.created_at)}</small></div></div>`).join(''):'<p class="muted">Your research, reviews, and publishing activity will appear here.</p>';}
function clientRow(c){const busy=['inspecting','planning'].includes(c.status);return `<div class="client-row"><div class="site-icon">${esc((c.name||new URL(c.url).hostname).slice(0,1).toUpperCase())}</div><div class="grow"><h3><button class="text-link" data-client="${esc(c.id)}">${esc(c.name||c.url)}</button></h3><small>${esc(c.url)}</small></div>${busy?'<span class="spinner"></span>':''}${badge(c.status)}<div class="actions"><button class="button small" data-client="${esc(c.id)}">Open workspace ↗</button></div></div>`;}
// Article pipeline: every article sits in exactly one stage, ordered by what needs the user first.
const STAGES=[
  {key:'attention',title:'Needs you',hint:'Held by review, failed, or not confirmed live'},
  {key:'progress',title:'In progress',hint:'Queued or being written, reviewed, or published'},
  {key:'ready',title:'Ready to publish',hint:'Written and reviewed, not live yet'},
  {key:'planned',title:'Not written yet',hint:'Planned topics waiting their turn'},
  {key:'published',title:'Published',hint:'Live on the website'}];
let articleFilter=null,articleClientFilter='';
const articleJob=a=>state.jobs.find(j=>j.article_id===a.id&&['queued','running'].includes(j.status));
const clientJob=id=>state.jobs.find(j=>j.client_id===id&&['queued','running'].includes(j.status));
function stageOf(a){if(articleJob(a)||['writing','reviewing','generating_cover','publishing'].includes(a.status))return 'progress';if(['held','error','verification_pending'].includes(a.status))return 'attention';if(['ready','exported'].includes(a.status))return 'ready';if(['published','refreshed'].includes(a.status))return 'published';if(a.status==='planned')return 'planned';return null;}
// The scheduler writes a planned article once both the client's weekly run and the article's own date are due.
function writeDate(c,a){const run=c?.next_run,own=a?.scheduled_at;return !run?own:!own?run:(new Date(run)>new Date(own)?run:own);}
function nextPlanned(clientId){return state.articles.filter(a=>a.client_id===clientId&&a.status==='planned'&&!articleJob(a)).sort((a,b)=>String(a.scheduled_at||'').localeCompare(String(b.scheduled_at||'')))[0];}
const STOPPABLE=['inspect','plan','generate','review','cover','seo-sync','backlinks-discover','backlink-check','visibility-audit','visibility-research','visibility-action','visibility-probe','style','brand-guide'];
// Queued work can always be stopped; running work only outside publishing and live checks.
function stopButton(j,small=true){if(!j||!(j.status==='queued'||j.status==='running'&&STOPPABLE.includes(j.kind)))return '';return `<button class="button ${small?'small':''}" data-action="stop-job" data-id="${esc(j.id)}" ${j.stage==='Stopping…'?'disabled':''}>${j.stage==='Stopping…'?'Stopping…':'Stop'}</button>`;}
function jobLabel(j){const a=j.article_id&&state.articles.find(x=>x.id===j.article_id),t=a?`“${a.title}”`:'';const names={inspect:'Inspecting the website',plan:'Building the article plan',generate:`Writing ${t}`,review:`Reviewing ${t}`,cover:`Creating a cover for ${t}`,publish:`Publishing ${t}`,verify:`Checking ${t} is live`,'seo-sync':'Syncing Google data','backlinks-discover':'Researching link opportunities','backlink-check':'Checking a tracked link','visibility-audit':'Running a visibility audit','visibility-research':'Researching opportunities','visibility-action':'Preparing an opportunity draft','visibility-probe':'Sampling AI answers',style:'Learning the cover style from approved covers','brand-guide':'Scanning the brand website for the cover guide'};return (names[j.kind]||label(j.kind))+(j.status==='queued'?' (queued)':'');}
function articleState(a){const job=articleJob(a);if(job)return {text:job.status==='queued'?'Queued':esc(job.stage||'Working…'),cls:'warning',busy:true};
  const c=client(a.client_id),next=nextPlanned(a.client_id);
  switch(a.status){
    case 'planned':return {text:next?.id===a.id?(c?.automation?'Up next · writes '+date(writeDate(c,a)):'Up next'):'Not written yet',cls:'neutral'};
    case 'writing':return {text:'Writing…',cls:'warning',busy:true};
    case 'reviewing':return {text:'Reviewing…',cls:'warning',busy:true};
    case 'generating_cover':return {text:'Creating cover…',cls:'warning',busy:true};
    case 'publishing':return {text:'Publishing…',cls:'warning',busy:true};
    case 'held':return {text:'Held by review: fix the findings',cls:'danger'};
    case 'error':return {text:'Failed: '+esc(a.error||'see details'),cls:'danger'};
    case 'verification_pending':{const d=a.publish_result?.deployment?.state;if(['ERROR','CANCELED'].includes(d))return {text:'Vercel build failed',cls:'danger'};if(d==='READY')return {text:'Deployed · article not visible on the page yet',cls:'warning'};if(client(a.client_id)?.connection?.provider==='vercel')return {text:'Vercel is deploying…',cls:'warning',busy:true};return {text:'Deployed, not confirmed live yet',cls:'warning'};}
    case 'ready':return {text:c?.connection?.auto_publish?'Ready · publishes automatically':'Ready · waiting for you to publish',cls:'success'};
    case 'exported':return {text:'Saved to the project, not live',cls:'warning'};
    case 'published':return {text:'Live',cls:'success'};
    case 'refreshed':return {text:'Live · replaced by a refresh',cls:'neutral'};
    default:return {text:esc(label(a.status)),cls:'neutral'};}}
function articleAction(a){const busy=!!clientJob(a.client_id),dis=busy?'disabled title="Another job for this website is running"':'',id=esc(a.id);
  switch(stageOf(a)){
    case 'planned':return `<button class="button small" data-action="generate" data-id="${id}" ${dis}>Write now</button>`;
    case 'attention':return a.status==='verification_pending'?(a.publish_result?.deployment?.inspector_url&&['ERROR','CANCELED'].includes(a.publish_result.deployment.state)?`<a class="button small" href="${esc(safeURL(a.publish_result.deployment.inspector_url))}" target="_blank" rel="noopener noreferrer">Open in Vercel ↗</a>`:`<button class="button small" data-action="verify" data-id="${id}" ${dis}>Check again</button>`):`<button class="button small" data-article="${id}" data-open-tab="review">Open &amp; fix</button>`;
    case 'ready':return client(a.client_id)?.connection?.project_path||a.status==='exported'?`<button class="button primary small" data-action="publish" data-id="${id}" ${dis}>Publish</button>`:`<button class="button small" data-action="connection" data-id="${esc(a.client_id)}">Connect website</button>`;
    case 'progress':return stopButton(articleJob(a));
    case 'published':{const url=a.publish_result?.live_url;return url?`<a class="button small" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">View live ↗</a>`:'';}
    default:return '';}}
function articleDate(a){if(['published','refreshed'].includes(a.status))return a.published_at?'Published '+date(a.published_at):'Published';if(!a.scheduled_at)return '';return (a.status==='planned'?'Planned for ':'Target date ')+date(a.scheduled_at);}
function pipeline(items,{showClient=false}={}){
  items=items.filter(a=>stageOf(a));
  if(!items.length)return '<div class="empty"><div class="empty-symbol">▤</div><h2>Your content starts here</h2><p>Inspect a website and choose a subject to build your first twelve-week plan.</p></div>';
  const counts=Object.fromEntries(STAGES.map(s=>[s.key,items.filter(a=>stageOf(a)===s.key).length]));
  const order=Object.fromEntries(STAGES.map((s,i)=>[s.key,i]));
  const shown=items.filter(a=>!articleFilter||stageOf(a)===articleFilter).sort((a,b)=>order[stageOf(a)]-order[stageOf(b)]||(stageOf(a)==='published'?String(b.published_at||'').localeCompare(String(a.published_at||'')):String(a.scheduled_at||'').localeCompare(String(b.scheduled_at||''))));
  return `<div class="pipeline-stages" role="group" aria-label="Filter articles by stage">${STAGES.map(s=>`<button class="pipeline-stage ${s.key} ${articleFilter===s.key?'active':''}" data-stage="${s.key}" aria-pressed="${articleFilter===s.key}" ${counts[s.key]?'':'data-empty="true"'}><strong>${counts[s.key]}</strong><span>${s.title}</span><small>${s.hint}</small></button>`).join('')}</div>
  ${articleFilter?`<p class="hint pipeline-filter">Showing ${esc(STAGES.find(s=>s.key===articleFilter).title.toLowerCase())} only. <button class="text-link" data-stage="${articleFilter}">Show all articles</button></p>`:''}
  <div class="pipeline-list">${shown.map(a=>{const s=articleState(a);return `<div class="pipeline-row stage-${stageOf(a)}"><div class="pipeline-main"><button class="text-link" data-article="${esc(a.id)}">${esc(a.title||'Untitled article')}</button><small>${esc([showClient?client(a.client_id)?.name||client(a.client_id)?.url||'Website':'',articleDate(a)].filter(Boolean).join(' · '))}</small></div><div class="pipeline-status"><span class="badge ${s.cls}">${s.busy?'<span class="spinner"></span>':''}${s.text}</span></div><div class="pipeline-action">${articleAction(a)}</div></div>`;}).join('')||'<p class="muted">No articles in this stage.</p>'}</div>`;}
// What happens next for one website, in plain language, including anything that silently blocks the schedule.
function scheduleSummary(c){if(!c.confirmed||!c.subject)return '';const job=clientJob(c.id),next=nextPlanned(c.id),failed=state.jobs.find(j=>j.client_id===c.id&&j.status==='failed'&&['inspect','plan','generate','review','cover','publish','verify'].includes(j.kind));
  let line,cls='';
  if(job)line=`<strong>Now:</strong> ${esc(jobLabel(job))}. Other actions for this website wait until it finishes. ${stopButton(job)}`;
  else if(!state.articles.some(a=>a.client_id===c.id&&stageOf(a)))line='<strong>No article plan yet.</strong> Build one to start writing.';
  else if(!c.automation)line=next?`<strong>Weekly schedule is off.</strong> Next in the plan: “${esc(next.title)}”. Use <em>Write now</em> to start it.`:'<strong>Weekly schedule is off</strong> and every planned article is written.';
  else if(state.settings.paused){line='<strong>Workspace automation is paused</strong> in Settings, so nothing runs on schedule.';cls='warning';}
  else if(failed){line=`<strong>Weekly schedule is blocked:</strong> the last job failed (${esc(jobLabel(failed))}). Retry it or dismiss it to resume. <button class="button small" data-action="retry" data-id="${esc(failed.id)}">Retry</button><button class="button ghost small" data-action="dismiss-job" data-id="${esc(failed.id)}">Dismiss</button>`;cls='warning';}
  else if(!['active','ready'].includes(c.status)){line=`<strong>Weekly schedule is waiting:</strong> the website is ${esc(label(c.status).toLowerCase())}.`;cls='warning';}
  else line=next?`<strong>Next:</strong> “${esc(next.title)}” will be written on ${esc(date(writeDate(c,next)))}. ${c.connection?.auto_publish?'It publishes automatically after review.':'It will wait for you to publish.'}`:`<strong>Next:</strong> a new plan will be built on ${esc(date(c.next_run))}.`;
  return `<div class="notice schedule-summary ${cls}" role="status">${line}</div>`;}
function overview(){const published=state.articles.filter(a=>a.status==='published').length;const attention=state.articles.filter(a=>['held','error'].includes(a.status)).length+state.clients.filter(c=>['error','needs_confirmation'].includes(c.status)).length;const running=state.jobs.filter(j=>['queued','running'].includes(j.status));return heading('Your content, moving forward.','Research once. Build authority, one useful article at a time.',`<span class="badge ${state.settings.paused?'warning':'success'}">${state.settings.paused?'Automation paused':'Weekly cadence'}</span>`)+`<div class="stats">${[['Connected websites',state.clients.length,'Each with its own strategy'],['Published articles',published,'Verified on client websites'],['In progress',running.length,'Research, writing & review'],['Needs attention',attention,'Decisions and exceptions']].map(([a,b,c])=>`<div class="card stat"><div class="stat-label">${a}<span>↗</span></div><div class="stat-value">${b.toString().padStart(2,'0')}</div><div class="stat-note">${c}</div></div>`).join('')}</div>${state.settings.paused?'<div class="notice warning">Workspace automation is paused. Resume it in Settings when you are ready.</div>':''}<div class="grid-two"><div class="stack"><section class="card"><div class="card-head"><h2>Your websites</h2><button class="button ghost small" data-nav="clients">View all ↗</button></div>${state.clients.length?`<div class="client-list">${state.clients.slice(0,4).map(clientRow).join('')}</div>`:`<div class="empty"><div class="empty-symbol">↗</div><h2>Meet your first website.</h2><p>Add a client’s URL. RankMe studies the business, maps existing content, and helps you choose what to write next.</p><button class="button primary" data-action="add">＋ Add your first website</button><div class="hint" style="margin-top:15px">Start with a URL. Connect publishing later.</div></div>`}</section><section class="card"><div class="card-head"><h2>Recent activity</h2><button class="button ghost small" data-nav="activity">View activity ↗</button></div>${eventRows(state.events.slice(0,4))}</section></div><div class="stack"><section class="card"><span class="eyebrow">THE RANKME WORKFLOW</span><h2 style="margin-bottom:25px">From website to weekly.</h2><div class="steps">${[['Understand the business','AI inspects services, audience, voice, and existing content.'],['Choose your direction','Confirm the profile and pick the subject that matters.'],['Keep content moving','Research, write, review, and publish every seven days.']].map(([title,desc],i)=>`<div class="step"><span class="step-number">0${i+1}</span><div><h3>${title}</h3><p>${desc}</p></div></div>`).join('')}</div></section>${health()}</div></div>`;}
function detail(c){
  if(!c)return heading('Website not found','Choose a website from Clients.');
  if(clientTab==='visibility')return heading(c.name||c.url,c.url,`<button class="button" data-nav="clients">← All websites</button>`)+clientTabs(c)+visibilityWorkspace(c);
  if(clientTab==='seo')return heading(c.name||c.url,c.url,`<button class="button" data-nav="clients">← All websites</button>`)+clientTabs(c)+seoWorkspace(c);
  const p=c.profile||{},hasProfile=Object.keys(p).length>0,items=articlesFor(c.id);
  const running=state.jobs.find(j=>j.client_id===c.id&&['running','queued'].includes(j.status));
  const step=!c.confirmed?1:!c.subject?2:3;
  const button=(action,text,primary=false)=>`<button class="button ${primary?'primary':''}" data-action="${action}" data-id="${esc(c.id)}" ${running?'disabled':''}>${text}</button>`;
  let next;
  if(running)next=`<span class="eyebrow">WORK IN PROGRESS</span><h2>${esc(jobLabel(running))}</h2><p>${esc(running.stage||'Queued and waiting to start.')}</p><div class="actions">${stopButton(running,false)}</div><p class="hint">You can leave this page. Progress is saved automatically.</p>`;
  else if(!c.confirmed&&hasProfile)next=`<span class="eyebrow">YOUR NEXT STEP · 1 OF 3</span><h2>Check what RankMe learned</h2><p>Review the company’s services, audience, and writing style. Correct anything wrong, then confirm the profile so RankMe can plan relevant articles.</p>${button('profile','Review & confirm business profile',true)}<p class="hint">Confirming saves your business brief. It does not publish anything.</p>`;
  else if(!c.confirmed)next=`<span class="eyebrow">STEP 1 OF 3</span><h2>${c.error?'Inspection needs attention':'Inspect the website first'}</h2><p>RankMe needs a business profile before planning articles.</p>${button('inspect',c.error?'Retry website inspection':'Inspect website',true)}`;
  else if(!c.subject)next=`<span class="eyebrow">YOUR NEXT STEP · 2 OF 3</span><h2>What should we write about?</h2><p>Your business profile is confirmed. Choose a subject to build a focused twelve-week article plan.</p>${button('subject','Choose a subject',true)}`;
  else next=`<span class="eyebrow">CONTENT DIRECTION</span><h2>${esc(c.subject)}</h2><p>${c.automation?'One article every seven days.':'Your plan is ready to work on. Generate an article or set up weekly automation below.'}</p><div class="actions">${items.some(a=>a.status==='planned')?button('run','Generate next article',true):button('subject','Build an article plan',true)}${items.some(a=>a.status==='planned')?button('subject','Change subject'):''}</div>`;
  const list=values=>`<ul class="detail-list">${values.map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`;
  const summary=p.summary?`<p class="profile-summary">${esc(p.summary)}</p>`:'<p class="muted">The business summary will appear after inspection.</p>';
  return heading(c.name||c.url,c.url,`<button class="button" data-nav="clients">← All websites</button>`)+clientTabs(c)+`<div class="client-workspace">
    <ol class="setup-steps" aria-label="Website setup">${['Confirm business','Choose subject','Create articles'].map((name,i)=>`<li class="${i+1<step?'complete':i+1===step?'current':''}" ${i+1===step?'aria-current="step"':''}><span>${i+1<step?'✓':i+1}</span>${name}</li>`).join('')}</ol>
    ${c.error?`<div class="notice error">${esc(c.error)}</div>`:''}
    <section class="card next-step">${next}</section>
    ${hasProfile?`<section class="card business-overview"><div class="card-head"><h2>Business at a glance</h2>${c.confirmed?'<span class="badge success">Profile confirmed</span>':''}</div>${summary}
      <details class="disclosure"><summary>Services, audience & writing style</summary><div class="disclosure-body"><h3>Services / products</h3>${list(p.services||[])}<h3>Audience</h3><p>${esc(p.audience||'Not established')}</p><h3>Writing style</h3><p>${esc(p.tone||'Not established')}</p><h3>Language</h3><p>${esc(p.language||'Not established')}</p>${c.confirmed?button('profile','Edit business profile'):''}</div></details>
      ${p.unknowns?.length?`<details class="disclosure"><summary>Missing information & inspection limits <span class="count">${p.unknowns.length}</span></summary><div class="disclosure-body"><p class="muted">These are gaps in the research, not a checklist you must complete. Keep genuine unknowns visible when reviewing the profile.</p>${list(p.unknowns)}</div></details>`:''}
      ${p.seo_findings?.length?`<details class="disclosure"><summary>Website inspection notes <span class="count">${p.seo_findings.length}</span></summary><div class="disclosure-body">${list(p.seo_findings)}</div></details>`:''}
    </section>`:''}
    ${c.confirmed?publishingCard(c):''}
    ${c.confirmed?coverStyleCard(c):''}
    ${c.confirmed&&c.subject?`<section class="card"><div class="card-head"><h2>Articles</h2><span class="muted">${items.filter(stageOf).length} in this plan</span></div>${scheduleSummary(c)}${pipeline(items)}</section>`:''}
    <details class="card disclosure setup-options"><summary>Website settings<span class="muted">${c.automation?'Weekly schedule on':'Weekly schedule off'}</span></summary><div class="disclosure-body settings-sections">
      <section><h3>Weekly schedule</h3><p class="muted">${c.automation?'Next run: '+time(c.next_run):'Off. No articles will run on a schedule until you enable it.'}</p><p class="hint">One article every seven days. Your computer must be awake.</p><div class="actions">${c.confirmed&&c.subject?`<button class="button" data-action="toggle-client" data-id="${esc(c.id)}">${c.automation?'Pause automation':'Enable weekly automation'}</button>${button('schedule','Set schedule')}`:'<p class="hint">Available after confirming the business and choosing a subject.</p>'}</div></section>
      <section><h3>Refresh website research</h3><p class="muted">Reinspection replaces the profile and asks you to confirm it again.</p>${button('inspect','Reinspect website')}</section>
      <section class="danger-zone"><h3>Remove website</h3><p class="muted">Deletes this website and all of its RankMe data. Nothing changes on the live website, GitHub, or Vercel.</p><button class="button danger" data-action="remove-client" data-id="${esc(c.id)}" ${running?'disabled title="Wait for the current job to finish"':''}>Remove website…</button></section>
    </div></details>
  </div>`;
}
function clientTabs(c){return `<div class="tabs client-tabs" role="tablist" aria-label="Client workspace"><button class="tab ${clientTab==='content'?'active':''}" role="tab" aria-selected="${clientTab==='content'}" data-client-tab="content" data-id="${esc(c.id)}">Content</button><button class="tab ${clientTab==='seo'?'active':''}" role="tab" aria-selected="${clientTab==='seo'}" data-client-tab="seo" data-id="${esc(c.id)}">SEO & links</button><button class="tab ${clientTab==='visibility'?'active':''}" role="tab" aria-selected="${clientTab==='visibility'}" data-client-tab="visibility" data-id="${esc(c.id)}">Visibility & autopilot</button></div>`;}
function visibilityReport(id){return (state.visibility||[]).filter(r=>r.client_id===id).sort((a,b)=>String(b.updated_at||b.created_at||'').localeCompare(String(a.updated_at||a.created_at||'')))[0];}
function visibilitySettings(c){const s={enabled:true,...(c.visibility_settings||{})};modal('Configure visibility autopilot',`<form id="visibility-settings-form" data-id="${esc(c.id)}"><p class="muted">Run a recurring public-page audit and prioritize opportunities using the data connected to this website.</p><div class="section"><label class="check-label"><input type="checkbox" name="enabled" ${s.enabled?'checked':''}>Enable recurring visibility audits</label></div><div class="form-grid section"><div class="field"><label for="visibility-interval">Audit every (days)</label><input id="visibility-interval" name="interval_days" type="number" min="1" max="30" required value="${esc(s.interval_days||7)}"></div><div class="field"><label for="visibility-limit">Maximum draft actions per run</label><input id="visibility-limit" name="max_actions" type="number" min="1" max="5" required value="${esc(s.max_actions||1)}"></div></div><label class="check-label"><input type="checkbox" name="auto_plan" ${s.auto_plan?'checked':''}>Automatically prepare content plans from eligible opportunities</label><label class="check-label"><input type="checkbox" name="auto_refresh" ${s.auto_refresh?'checked':''}>Automatically prepare refresh drafts for eligible articles</label><label class="check-label"><input type="checkbox" name="auto_research" ${s.auto_research?'checked':''}>Automatically research customer problems and competitor content</label><label class="check-label"><input type="checkbox" name="auto_probe" ${s.auto_probe?'checked':''}>Automatically sample Codex web answers for business queries</label><div class="notice section">RankMe must be running on an awake computer. Workspace pause stops scheduled work. Publishing follows this website’s separate publishing settings. Outreach is excluded. Research and answer sampling have separate per-cycle limits and use your Codex allowance.</div>${formActions('Save autopilot settings')}</form>`);}
function evidenceHTML(value){if(value===null||value===undefined)return '<p class="muted">No evidence recorded.</p>';if(typeof value!=='object')return `<p>${esc(value)}</p>`;if(Array.isArray(value))return `<ul class="detail-list">${value.map(v=>`<li>${typeof v==='object'?evidenceHTML(v):esc(v)}</li>`).join('')}</ul>`;return `<dl class="visibility-evidence">${Object.entries(value).map(([k,v])=>`<div><dt>${esc(label(k))}</dt><dd>${typeof v==='object'?evidenceHTML(v):esc(v)}</dd></div>`).join('')}</dl>`;}
function visibilityOpportunity(id){const o=(state.opportunities||[]).find(o=>o.id===id);if(!o)return;modal(o.title||'Visibility opportunity',`<div class="actions">${badge(o.kind||o.type)}${badge(o.status||'open')}<strong>Priority ${esc(o.score??'—')}/100</strong></div><p class="section">${esc(o.score_explanation||o.explanation||'Review the evidence before selecting a next step.')}</p>${o.conversion_score_reason?`<div class="notice section"><strong>Conversion evidence in this priority</strong><p>${esc(o.conversion_score_reason)}</p></div>`:''}${o.url?`<p class="section"><a href="${esc(safeURL(o.url))}" target="_blank" rel="noopener noreferrer">${esc(o.url)}</a></p>`:''}<h3 class="section">Evidence</h3>${evidenceHTML(o.evidence)}${o.brief?`<h3 class="section">Content brief</h3>${evidenceHTML(o.brief)}`:''}${o.error?`<div class="notice error section">${esc(o.error)}</div>`:''}${o.task_id?`<button class="button small" data-action="visibility-task" data-id="${esc(o.task_id)}">Open brief</button>`:''}${o.article_id?`<button class="button primary section" data-article="${esc(o.article_id)}">Open article</button>`:''}<p class="hint section">Priority is a local heuristic for this queue, not a ranking prediction.</p>`,true);}
function opportunityRows(items){return items.map(o=>`<div class="visibility-opportunity"><div class="visibility-score" aria-label="Priority score ${esc(o.score??'unknown')} out of 100">${esc(o.score??'—')}<small>/100</small></div><div class="grow"><div class="actions">${badge(o.kind||o.type)}${badge(o.status||'open')}</div><h3><button class="text-link" data-action="opportunity-details" data-id="${esc(o.id)}">${esc(o.title||'Review opportunity')}</button></h3><p>${esc(o.score_explanation||o.explanation||'Review the supporting evidence to decide your next step.')}</p>${o.url?`<a class="hint" href="${esc(safeURL(o.url))}" target="_blank" rel="noopener noreferrer">${esc(o.url)}</a>`:''}</div><div class="actions visibility-opportunity-actions"><button class="button small" data-action="opportunity-details" data-id="${esc(o.id)}">Evidence</button>${o.status==='dismissed'?`<button class="button small" data-action="opportunity-reopen" data-id="${esc(o.id)}">Reopen</button>`:!['completed','executed','queued','running','resolved','stale'].includes(o.status)?`${visibilityExecutable(o)?`<button class="button primary small" data-action="opportunity-execute" data-id="${esc(o.id)}">${esc(o.execution_label||'Prepare draft')}</button>`:''}<button class="button ghost small" data-action="opportunity-dismiss" data-id="${esc(o.id)}">Dismiss</button>`:''}${o.task_id?`<button class="button small" data-action="visibility-task" data-id="${esc(o.task_id)}">Open brief</button>`:''}${o.article_id?`<button class="button small" data-article="${esc(o.article_id)}">Open article</button>`:''}</div></div>`).join('');}
function visibilityTask(id){const t=(state.tasks||[]).find(t=>t.id===id);if(!t)return;modal(t.title||'Prepared task',`<div class="actions">${badge(t.kind)}${badge(t.status||'ready')}</div><article class="article-preview">${markdown(t.body||'No brief text recorded.')}</article>${t.sources?.length?`<h3 class="section">Sources</h3>${t.sources.map(source=>{const url=typeof source==='string'?source:source.url;return `<div class="source"><a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(typeof source==='string'?source:source.title||url)}</a></div>`;}).join('')}`:''}`,true);}
function visibilityExecutable(o){return o.executable===true;}
function answerProbesHTML(probes){const records=probes?.records||[];return `<section class="card"><div class="card-head"><div><h2>AI answer samples</h2><p class="hint">Actual Codex web answers for up to three business queries. These are not measurements of consumer ChatGPT, Claude, Gemini, or Perplexity.</p></div></div>${records.length?records.map(r=>`<details class="disclosure"><summary>${esc(r.prompt)}<span class="hint">${esc(r.provider||'Codex web answer')} · ${esc(time(r.observed_at))}</span></summary><div class="disclosure-body"><div class="actions"><span class="badge ${r.brand_mentioned?'success':'neutral'}">Brand ${r.brand_mentioned?'mentioned':'not mentioned'}</span><span class="badge ${r.target_cited?'success':'warning'}">Website ${r.target_cited?'cited':'not cited'}</span></div><article class="article-preview">${markdown(r.answer||'No answer text recorded.')}</article><h3>Citations in this sample</h3>${r.citations?.length?r.citations.map(c=>`<div class="source"><a href="${esc(safeURL(c.url))}" target="_blank" rel="noopener noreferrer">${esc(c.title||c.url)}</a> <span class="badge ${c.verified?'success':'neutral'}">${c.verified?'Reachable':'Not verified'}</span></div>`).join(''):'<p class="muted">No citations recorded for this answer.</p>'}${!r.target_cited&&r.citations?.length?'<p class="hint section">Citation gap in this sample: other sources were cited, while this website was not. Review the cited pages before choosing an action.</p>':''}</div></details>`).join(''):'<p class="muted">No answer samples yet. Use “Sample AI answers” to collect a small, attributed baseline. Missing samples are not zero visibility.</p>'}${probes?.limitations?.length?`<ul class="detail-list section">${probes.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>`:''}</section>`;}
function conversionGoalModal(c){const g=c.conversion_goal||{};modal('Define a conversion goal',`<form id="conversion-goal-form" data-id="${esc(c.id)}"><p class="muted">Choose the customer action this website should earn. Connect the matching Google Analytics event to measure it.</p><div class="field section"><label for="goal-type">Customer action</label><select id="goal-type" name="goal_type">${[['signup','Sign up'],['purchase','Purchase'],['booking','Book an appointment'],['lead','Submit an inquiry']].map(([value,title])=>`<option value="${value}" ${g.goal_type===value?'selected':''}>${title}</option>`).join('')}</select></div>${field('event_name','Google Analytics event name',g.event_name||'','text','Use the exact existing event name, such as sign_up or generate_lead.')}${field('landing_page','Goal landing page',g.landing_page||'','url','Required: an absolute URL on this website, such as https://example.com/book.')}<p class="hint">Saving a goal does not create the event in Google Analytics or change your website. Historical observations retain the goal used when they were collected.</p>${g.goal_type?`<button type="button" class="button danger section" data-action="conversion-goal-clear" data-id="${esc(c.id)}">Remove goal</button>`:''}${formActions('Save conversion goal')}</form>`);}
function conversionStatusHTML(measurement){const measured=measurement.status==='measured',row=measurement.current||{};return `<div class="goal-measurement section"><div class="actions"><strong>Current measurement</strong><span class="badge ${measured?'success':'warning'}">${esc(label(measurement.status||'unavailable'))}</span></div>${measured?`<div class="goal-measurement-counts"><div><strong>${metric(row.organic_sessions)}</strong><span>Goal organic sessions</span></div><div><strong>${metric(row.conversions)}</strong><span>Goal event occurrences</span></div></div><p class="hint">${esc(date(row.start))} – ${esc(date(row.end))} · ${esc(row.event_name||measurement.goal?.event_name||'')}</p>`:'<p class="hint">No current comparable measurement. Historical counts below remain evidence of their original settings.</p>'}${measurement.issues?.length?`<ul class="detail-list section">${measurement.issues.map(issue=>`<li>${esc(issue)}</li>`).join('')}</ul>`:''}${measurement.note?`<p class="hint section">${esc(measurement.note)}</p>`:''}</div>`;}
function goalHistory(c){
 const g=c.conversion_goal||{},configured=!!g.goal_type,conversion=visibilityReport(c.id)?.conversion_measurement||{status:configured?'unavailable':'unconfigured',issues:configured?['Run an audit and sync Google to establish a current measurement.']:[]},measurements=(state.measurements||[]).filter(m=>m.client_id===c.id).sort((a,b)=>String(b.observed_at||b.created_at||'').localeCompare(String(a.observed_at||a.created_at||''))),experiments=(state.experiments||[]).filter(x=>x.client_id===c.id).sort((a,b)=>String(b.started_at||b.created_at||'').localeCompare(String(a.started_at||a.created_at||''))),measurementCount=state.measurement_counts?.[c.id]??measurements.length;
 return `<section class="card"><div class="card-head"><div><span class="eyebrow">BUSINESS OUTCOMES</span><h2>${configured?esc(label(g.goal_type)):'Define the action that matters'}</h2></div><button class="button" data-action="conversion-goal" data-id="${esc(c.id)}">${configured?'Edit conversion goal':'Set conversion goal'}</button></div>${configured?`<p class="muted">Analytics event: <strong>${esc(g.event_name||'Not configured')}</strong></p>${g.landing_page?`<p class="section"><a href="${esc(safeURL(g.landing_page))}" target="_blank" rel="noopener noreferrer">${esc(g.landing_page)}</a></p>`:''}`:'<p class="muted">Choose signups, purchases, bookings, or inquiries. Without a configured goal and matching analytics observations, conversion impact is unknown.</p>'}${conversionStatusHTML(conversion)}<p class="hint section">Conversions need a connected Analytics property and a matching event. Search visibility alone does not establish business impact.</p></section>
 <section class="card"><div class="card-head"><div><h2>Measurement history</h2><p class="hint">Saved observations retain their dates, source, and measurement scope.</p></div><div class="actions"><span class="badge neutral">${measurementCount} observations</span>${measurementCount?`<a class="button small" href="/api/clients/${encodeURIComponent(c.id)}/measurement-history" download>${hosted?'Download synced history':'Download full history'}</a>`:''}</div></div>${measurements.length?`<div class="table-wrap"><table><thead><tr><th>OBSERVED</th><th>PERIOD</th><th>CLICKS</th><th>IMPRESSIONS</th><th>GOAL ORGANIC SESSIONS</th><th>GOAL EVENT OCCURRENCES</th><th></th></tr></thead><tbody>${measurements.slice(0,20).map(m=>{const snapshot=m.snapshot||{},cm=snapshot.conversion_measurement||{},totals=snapshot.search_console?.current?.totals||{},current=cm.current||{},period=snapshot.periods?.current||{};return `<tr><td>${esc(time(m.observed_at||m.created_at))}<small>${esc(label(m.source||'observation'))}</small></td><td>${period.start?`${esc(date(period.start))} – ${esc(date(period.end))}`:'—'}</td><td>${metric(totals.clicks)}</td><td>${metric(totals.impressions)}</td><td>${metric(current.organic_sessions)}</td><td>${metric(current.conversions)}<small>${esc(current.event_name||cm.goal?.event_name||'')}</small></td><td><button class="button small" data-action="measurement-details" data-id="${esc(m.id)}">Evidence</button></td></tr>`;}).join('')}</tbody></table></div><p class="hint section">${measurementCount>20?'Showing the latest 20 observations. ':''}Unavailable values appear as —, never zero. Goal counts use the configured landing page and Organic Search scope. Event occurrences may repeat for one customer. Overlapping windows are not independent observations.</p>`:'<div class="visibility-history-empty"><h3>No measurements saved yet</h3><p class="muted">History appears after connected data is collected. A missing measurement is not evidence of no traffic or no conversions.</p></div>'}</section>
 <section class="card"><div class="card-head"><div><h2>Content experiments</h2><p class="hint">Track a change, its baseline, and subsequent observations.</p></div><div class="actions"><span class="badge neutral">${experiments.length} tracked</span><button class="button" data-action="experiment-create" data-id="${esc(c.id)}" ${configured&&conversion.status==='measured'?'':'disabled'}>Track a change</button></div></div><div class="notice">Before-and-after changes are observational. Seasonality, competitors, tracking changes, and other edits can affect results; these comparisons do not establish causation.</div>${experiments.length?experiments.map(x=>`<details class="disclosure"><summary>${esc(x.hypothesis||x.title||'Content experiment')} <span class="badge ${x.status==='improved'?'success':x.status==='declined'?'danger':'neutral'}">${esc(label(x.status||'observing'))}</span><span class="hint">Started ${esc(date(x.started_at||x.created_at))}</span></summary><div class="disclosure-body">${x.page_url?`<p><a href="${esc(safeURL(x.page_url))}" target="_blank" rel="noopener noreferrer">${esc(x.page_url)}</a></p>`:''}<h3>Change recorded</h3><p>${esc(x.change||'No change description recorded.')}</p><h3>Interpretation</h3><p>${esc(x.interpretation||x.evaluation?.reason||'Waiting for comparable follow-up observations.')}</p>${x.evaluation?.note?`<p class="hint">${esc(x.evaluation.note)}</p>`:''}<div class="experiment-comparison"><section><h3>Baseline</h3>${evidenceHTML(x.baseline)}</section><section><h3>Current observation</h3>${evidenceHTML(x.evaluation?.current)}</section></div><p class="hint">Comparison uses event occurrences per organic session, not the percentage of customers who converted. One customer may trigger an event more than once.</p>${['observing','observation'].includes(x.status||'observing')?`<button class="button danger" data-action="experiment-cancel" data-id="${esc(x.id)}">Cancel tracking</button>`:''}</div></details>`).join(''):'<div class="visibility-history-empty"><h3>No experiments tracked yet</h3><p class="muted">Configure a goal and sync a measured Analytics baseline before tracking a change. Follow-up results remain undecided when observations are missing or not comparable.</p></div>'}</section>`;
}
function experimentModal(c){modal('Track a content change',`<form id="experiment-form" data-id="${esc(c.id)}"><p class="muted">Record a change made today and the outcome you expect. RankMe compares subsequent observations against the latest measured goal baseline. Older changes need their original baseline and cannot be recorded with this form.</p><div class="section">${field('page_url','Changed page URL',c.conversion_goal?.landing_page||'','url','Use an absolute URL on this website.')}${field('hypothesis','Expected outcome','','textarea','Describe the change and why you expect it to improve the configured goal.')}${field('change','Change made','','textarea','Describe exactly what changed, such as the headline, internal links, or content update.')}</div><div class="notice">This records an observational comparison, not a randomized test. Tracking a change does not modify or publish the page.</div>${formActions('Track change')}</form>`);}
function measurementDetails(id){const m=(state.measurements||[]).find(m=>m.id===id);if(!m)return;modal('Measurement evidence',`<p class="muted">Saved ${esc(time(m.observed_at||m.created_at))}. Missing values are unknown.</p><pre class="measurement-json">${esc(JSON.stringify(m,null,2))}</pre>`,true);}

function visibilityWorkspace(c){
  const report=visibilityReport(c.id),s={enabled:true,...(c.visibility_settings||{})},all=(state.opportunities||[]).filter(o=>o.client_id===c.id),open=all.filter(o=>['open','error','failed'].includes(o.status||'open')).sort((a,b)=>(b.score||0)-(a.score||0)),history=all.filter(o=>!open.includes(o)),running=state.jobs.find(j=>j.client_id===c.id&&['queued','running'].includes(j.status)),findings=report?.technical_findings||[],clusters=report?.topical_clusters||[],caps=report?.capabilities||[],coverage=report?.coverage||{};
  return `<div class="visibility-workspace"><section class="card visibility-hero"><div class="card-head"><div><span class="eyebrow">VISIBILITY & AUTOPILOT</span><h2>A clear next step for every website.</h2></div><div class="actions"><button class="button" data-action="visibility-settings" data-id="${esc(c.id)}">Configure autopilot</button><button class="button" data-action="visibility-probe" data-id="${esc(c.id)}" ${running?'disabled':''}>Sample AI answers</button><button class="button" data-action="visibility-research" data-id="${esc(c.id)}" ${running?'disabled':''}>Research opportunities</button><button class="button primary" data-action="visibility-audit" data-id="${esc(c.id)}" ${running?'disabled':''}>${report?'Run fresh audit':'Run first audit'}</button></div></div><p>Turn public-page checks, search performance, and tracked links into a scored opportunity queue with supporting evidence.</p>${report?`<a class="button small section" href="/api/clients/${encodeURIComponent(c.id)}/visibility-report" download>Download report</a>`:''}<div class="visibility-run-status">${badge(state.settings.paused?'paused':s.enabled?'active':'off')}<span>${s.enabled?`Audits every ${esc(s.interval_days||7)} days`:'Recurring audits are off'}${report?` · Last crawl ${esc(time(report.crawl_observed_at))}`:''}</span></div>${running?`<div class="notice section" role="status"><span class="spinner"></span>${esc(running.stage||'A job is queued or running for this website.')} ${stopButton(running)}</div>`:''}${c.visibility_error?`<div class="notice error section">${esc(c.visibility_error)}</div>`:''}</section>
  <div class="stats visibility-stats">${[['Open opportunities',open.length,'Prioritized by local scoring'],['Pages checked',report?coverage.pages??'—':'—','Public HTML within the crawl limit'],['Search queries',report?coverage.queries??'—':'—','From connected Search Console data'],['Tracked links',report?coverage.backlinks??'—':'—','Known links, not a full backlink index']].map(([title,value,note])=>`<div class="card stat"><div class="stat-label">${title}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${note}</div></div>`).join('')}</div>
  ${report?.missing_data?.length?`<div class="notice warning"><strong>Expand your coverage</strong><ul class="detail-list">${report.missing_data.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></div>`:''}
  <section class="card"><div class="card-head"><div><h2>Your next opportunities</h2><p class="hint">Scores prioritize work; evidence explains why. Draft actions preserve a review step.</p></div><span class="badge neutral">${open.length} open</span></div>${open.length?opportunityRows(open):`<div class="empty"><div class="empty-symbol">↗</div><h2>${report?'No open opportunities':'Start with an evidence baseline'}</h2><p>${report?'This audit has no open recommendations. Review coverage and missing data before drawing conclusions.':'Run an audit to check public pages and combine available Google data and link records. Missing integrations stay visible.'}</p></div>`}${history.length?`<details class="disclosure"><summary>Completed, dismissed & previous opportunities <span class="count">${history.length}</span></summary>${opportunityRows(history)}</details>`:''}</section>
  ${report?`<div class="grid-two"><section class="card"><div class="card-head"><h2>Technical findings</h2><span class="badge neutral">${findings.length}</span></div>${findings.length?findings.slice(0,30).map(f=>`<div class="visibility-finding">${badge(f.severity||f.kind||'review')}<h3>${esc(f.title||f.message||f.issue||f.kind||'Finding')}</h3>${f.url?`<a href="${esc(safeURL(f.url))}" target="_blank" rel="noopener noreferrer">${esc(f.url)}</a>`:''}<p class="hint">${esc(f.detail||f.recommendation||f.description||f.score_explanation||'')}</p></div>`).join(''):'<p class="muted">No findings recorded within this audit’s crawl coverage.</p>'}<p class="hint section">Checks use fetched HTML. JavaScript rendering, full-site coverage, and Core Web Vitals are not implied.</p></section><section class="card"><div class="card-head"><h2>Topic coverage</h2></div>${clusters.length?clusters.slice(0,20).map(t=>`<div class="visibility-finding"><h3>${esc(t.topic||t.name||t.keyword||t.title||'Topic')}</h3>${evidenceHTML(t)}</div>`).join(''):'<p class="muted">Topic clusters appear when the audit has enough content or query evidence.</p>'}</section></div>`:''}
  ${goalHistory(c)}
  ${answerProbesHTML(report?.answer_probes)}
  <section class="card"><div class="card-head"><div><h2>Workflow coverage</h2><p class="hint">What runs now, what is partial, and what needs a connection.</p></div>${caps.length?`<span class="badge neutral">${caps.length} capabilities</span>`:''}</div>${caps.length?`<div class="visibility-capabilities">${caps.map(cap=>`<div class="visibility-capability"><div class="card-head"><h3>${esc(cap.name)}</h3>${badge(cap.status)}</div><p>${esc(cap.detail||cap.description||'')}</p></div>`).join('')}</div>`:'<p class="muted">Run the first audit to see a capability-by-capability coverage report. Actual Codex answer sampling is available; other AI platforms need their own integrations. Outreach is excluded.</p>'}</section>
  <details class="card disclosure setup-options"><summary>Connections & operating limits</summary><div class="disclosure-body"><p>Connect Search Console in SEO & links for real query performance. Confirm the business profile before content planning, and configure the publishing connection before enabling live publishing.</p><p>Codex answer samples show actual observations from that runner. Other AI platforms and comprehensive keyword/backlink data need their own integrations. Reports show unavailable data explicitly. Outreach and link exchanges are excluded.</p><div class="actions"><button class="button" data-client-tab="seo" data-id="${esc(c.id)}">SEO & links</button><button class="button" data-client-tab="content" data-id="${esc(c.id)}">Business & publishing</button></div></div></details></div>`;
}

function googleCard(){const google=state.google||{};if(hosted)return `<section class="card"><div class="card-head"><h2>Google connection</h2>${badge(google.connected?'connected':'not_connected')}</div><p class="muted">${esc(google.message||'Google access is configured and connected in RankMe on your Mac. Existing reports appear here after sync.')}</p><p class="hint">Open the Mac workspace to configure OAuth, sign in, or change properties.</p></section>`;return `<section class="card"><div class="card-head"><h2>Google connection</h2><span class="badge ${google.connected?'success':'neutral'}">${google.connected?'Connected':google.configured?'Ready to sign in':'Not configured'}</span></div><p class="muted">Read Search Console and optional Google Analytics data for the websites you manage.</p>${google.message?`<p class="hint">${esc(google.message)}</p>`:''}<div class="actions section">${!google.configured?'<button class="button primary small" data-action="google-setup">Set up Google access</button>':!google.connected?'<button class="button primary small" data-action="google-connect">Sign in with Google</button>':'<button class="button small" data-action="google-disconnect">Disconnect Google</button>'}${google.configured?'<button class="button small" data-action="google-setup">OAuth settings</button>':''}</div><p class="hint">${google.connected?'Disconnecting stops future data syncs for every client. Saved reports stay local.':'Google sign-in happens in your browser. RankMe never asks for your Google password.'}</p></section>`;}
function vercelCard(){const v=state.vercel||{};if(hosted)return `<section class="card"><div class="card-head"><h2>Vercel</h2>${badge(v.connected?'connected':'not_connected')}</div><p class="muted">Vercel is connected and managed in RankMe on your Mac.</p></section>`;
  return `<section class="card"><div class="card-head"><h2>Vercel</h2><span class="badge ${v.connected?'success':'neutral'}">${v.connected?'Connected':'Not connected'}</span></div>${v.connected?`<p class="muted">Signed in as <strong>${esc(v.user)}</strong>${v.teams?.length?` · ${v.teams.length} ${v.teams.length===1?'team':'teams'}`:''}. RankMe only reads project details and deployment status.</p><div class="actions section"><button class="button small" data-action="vercel-disconnect">Disconnect Vercel</button></div>`:`<p class="muted">Connect once, then choose the Vercel project for each website. RankMe pushes each approved article to the project’s GitHub repository; Vercel deploys it as usual.</p><form id="vercel-connect-form" class="section"><div class="field"><label for="vercel-token">Vercel access token</label><input id="vercel-token" name="token" type="password" autocomplete="off" spellcheck="false" required placeholder="Paste a token"><small class="hint">Create one at <a href="https://vercel.com/account/tokens" target="_blank" rel="noopener noreferrer">vercel.com/account/tokens</a> with access to the team that owns your sites. Stored only on this Mac.</small></div><button class="button primary small" type="submit">Connect Vercel</button></form>`}<div class="divider"></div><h3>GitHub</h3><p class="hint">Publishing uses this Mac’s existing GitHub sign-in, so no GitHub token is stored in RankMe. If a website check says GitHub is not reachable, run <code>gh auth login</code> in Terminal.</p></section>`;}
// Cover style: one rendering mode and art direction per website, plus approved covers that anchor consistency.
const COVER_MODES={illustration_3d:{title:'3D illustration',desc:'Polished 3D artwork in the brand colors: bright, clean, with objects readers recognize.',mood:'Bright, clean, friendly and reassuring',subjects:'A recognizable object or scene from the article, e.g. the product, tool, or situation readers know',avoid:'Abstract shapes, toy-like plastic, dark backgrounds'},
  photo:{title:'Realistic photography',desc:'Looks like a professional photo shoot: real materials, natural light, no AI look. Shows the problem and the fix.',mood:'Bright daylight, vivid natural colors, inviting and optimistic',subjects:'The real problem customers face and the fix in progress, as they would see it at their own home or site',avoid:'Dark or gloomy scenes, staged stock-photo people, visible faces, cluttered backgrounds'}};
const coverMode=c=>COVER_MODES[c.image_brand?.mode]?c.image_brand.mode:'illustration_3d';
function coverStyleCard(c){const b=c.image_brand||{},mode=COVER_MODES[coverMode(c)],refs=(b.references||[]).map(r=>state.articles.find(a=>a.id===r.article_id)).filter(a=>a?.cover?.path);
  const line=(k,t)=>b[k]?`<div><dt>${t}</dt><dd>${esc(b[k])}</dd></div>`:'';
  return `<section class="card cover-style-card"><div class="card-head"><div><span class="eyebrow">COVER STYLE</span><h2>${esc(mode.title)}</h2></div><button class="button small" data-action="cover-style" data-id="${esc(c.id)}">Edit cover style</button></div>
    <p class="muted">${esc(mode.desc)}</p>
    <div class="swatches section">${(b.colors||[]).map(col=>`<span class="swatch-chip"><span class="swatch" style="--swatch:${esc(col)}"></span>${esc(col)}</span>`).join('')||'<span class="hint">No brand colors yet. Add them or scan the brand website.</span>'}</div>
    ${b.mood||b.subjects||b.avoid||b.style?`<dl class="style-direction">${line('mood','Mood')}${line('subjects','What to show')}${line('avoid','Avoid')}${line('style','Visual direction')}</dl>`:''}
    ${brandSiteSection(c)}
    <h3 class="section">Style references</h3>${refs.length?`<div class="reference-strip">${refs.map(a=>`<button class="reference-thumb" data-article="${esc(a.id)}" title="${esc(a.title)}">${hosted?'':`<img src="/api/articles/${encodeURIComponent(a.id)}/cover?v=${encodeURIComponent(a.cover.sha256||'')}" alt="${esc(a.cover.alt||a.title)}" loading="lazy">`}<span>${esc(a.title)}</span></button>`).join('')}</div>${b.style_spec?`<p class="hint section"><strong>Learned house style:</strong> ${esc(b.style_spec)}</p>`:'<p class="hint section">RankMe is learning the shared style of these covers.</p>'}`:'<p class="hint">Open an approved cover and choose <em>Use as style reference</em>. Up to three references are attached to every new cover, and covers that drift from them fail review.</p>'}</section>`;}
const siteHost=c=>{try{return new URL(c.url).hostname.replace(/^www\./,'');}catch{return '';}};
function removeClientModal(c){const host=siteHost(c),count=state.articles.filter(a=>a.client_id===c.id).length,live=state.articles.filter(a=>a.client_id===c.id&&a.status==='published').length;
  modal('Remove '+(c.name||host)+'?',`<form id="remove-client-form" data-id="${esc(c.id)}"><div class="notice error">This permanently deletes the website from RankMe and cannot be undone.</div>
  <div class="remove-summary section"><div><h3>Deleted from RankMe</h3><ul class="detail-list"><li>Business profile, subject, and schedule</li><li>${count} ${count===1?'article':'articles'} with drafts, covers, and reviews</li><li>SEO, visibility, and measurement history</li><li>Brand guide, style references, and RankMe’s copy of the repository</li></ul></div>
  <div><h3>Not changed</h3><ul class="detail-list"><li>The live website${live?` and its ${live} published ${live===1?'article':'articles'}`:''}</li><li>The GitHub repository and Vercel project</li><li>Other websites in RankMe</li></ul></div></div>
  <p class="hint section">Want a copy first? <a href="/api/backup" download>Download a workspace backup</a>.</p>
  <div class="field section"><label for="remove-confirm">Type <strong>${esc(host)}</strong> to confirm</label><input id="remove-confirm" name="confirm" autocomplete="off" spellcheck="false" data-expected="${esc(host)}"></div>
  <div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button danger" type="submit" id="remove-submit" disabled>Remove website</button></div></form>`);$('#remove-confirm').focus();}
function brandSiteSection(c){const site=c.image_brand?.site||{},guide=site.analysis,job=state.jobs.find(j=>j.client_id===c.id&&j.kind==='brand-guide'&&['queued','running'].includes(j.status)),chosen=new Set(guide?.reference_images||[]);
  const thumbs=(site.images||[]).map((img,i)=>`<figure class="brand-thumb ${chosen.has(i)?'chosen':''}">${hosted?'':`<img src="/api/clients/${encodeURIComponent(c.id)}/brand-images/${encodeURIComponent(img.file)}" alt="Image from the brand website" loading="lazy">`}${chosen.has(i)?'<figcaption>Binding reference</figcaption>':''}</figure>`).join('');
  return `<div class="brand-site section"><div class="card-head"><div><h3>Brand website guide</h3><p class="hint">${site.url?`From <a href="${esc(safeURL(site.url))}" target="_blank" rel="noopener noreferrer">${esc(site.url.replace(/^https?:\/\//,''))}</a>${site.scanned_at?' · scanned '+esc(time(site.scanned_at)):''}`:'Not scanned yet. RankMe reads the website’s own images and colors and turns them into a guide every cover must follow.'}</p></div>${hosted?'':`<button class="button small" data-action="brand-site" data-id="${esc(c.id)}" ${job?'disabled':''}>${site.url?'Change or rescan':'Scan brand website'}</button>`}</div>
    ${job?`<p class="hint"><span class="spinner"></span>${esc(job.stage||'Waiting to scan the website')}</p>`:''}
    ${guide?`<p>${esc(guide.summary)}</p>${thumbs?`<div class="brand-strip">${thumbs}</div>`:''}<p class="hint section"><strong>Binding guide:</strong> ${esc(guide.style_spec)}</p>`:''}</div>`;}
function brandSiteModal(c){const site=c.image_brand?.site||{};modal('Brand website guide',`<form id="brand-site-form" data-id="${esc(c.id)}"><p class="muted">RankMe scans this website’s pages for its real photos and artwork (skipping logos, icons, people, and before/after images), reads its brand colors, and writes a guide that every cover for ${esc(c.name||c.url)} must follow.</p>${field('url','Brand reference website',site.url||c.url,'url','Use the site whose look the covers should match, for example its live domain.')}<p class="hint">Scanning uses your Codex subscription once to study the images. Colors, mood, what to show, and what to avoid are filled in only where you have not set them.</p>${formActions('Scan website')}</form>`);}
function colorRow(value){const hex=/^#[0-9a-fA-F]{6}$/.test(value||'')?value.toUpperCase():'#1B3A5C';return `<div class="color-row"><input type="color" value="${esc(hex)}" aria-label="Pick color" data-color-picker><input name="color-hex" value="${esc(value?hex:'')}" placeholder="#1B3A5C" maxlength="7" spellcheck="false" aria-label="Hex color" data-color-hex><span class="swatch" style="--swatch:${esc(value?hex:'transparent')}"></span><button type="button" class="button ghost small" data-action="color-remove">Remove</button></div>`;}
function coverStyleModal(c){const b=c.image_brand||{},current=coverMode(c);
  modal('Cover style',`<form id="cover-style-form" data-id="${esc(c.id)}"><p class="muted">Every cover for ${esc(c.name||c.url)} follows these settings, so articles look like one series.</p>
  <div class="mode-options section" role="radiogroup" aria-label="Rendering">${Object.entries(COVER_MODES).map(([key,m])=>`<label class="mode-option"><input type="radio" name="mode" value="${key}" ${key===current?'checked':''}><strong>${m.title}</strong><small>${m.desc}</small></label>`).join('')}</div>
  <p class="hint" id="mode-warning" hidden>Changing the rendering clears style references and marks unpublished covers for a new image.</p>
  <div class="field"><label>Brand colors</label><div id="color-rows">${(b.colors||[]).map(colorRow).join('')||colorRow('')}</div><button type="button" class="button small" data-action="color-add">＋ Add color</button><small class="hint">Pick a color or type its hex code. Up to six.</small></div>
  ${field('mood','Mood',b.mood||'','text','')}${field('subjects','What to show',b.subjects||'','textarea','')}${field('avoid','Avoid',b.avoid||'','textarea','')}
  <details class="disclosure"><summary>Extra visual direction</summary><div class="disclosure-body">${field('style','Visual direction',b.style||'','textarea','Materials, settings, or recurring elements that fit this website.')}</div></details>
  <p class="hint">Changing these settings marks covers of unpublished articles for regeneration. Published covers are never changed.</p>${formActions('Save cover style')}</form>`);coverModeChanged(current);}
function coverModeChanged(initial){const form=$('#cover-style-form');if(!form)return;const mode=form.mode.value,m=COVER_MODES[mode];for(const k of ['mood','subjects','avoid'])form[k].placeholder=m[k];const warn=$('#mode-warning');if(warn)warn.hidden=initial!==undefined||mode===coverMode(client(form.dataset.id));}
// Where this website's articles go live, and whether the site can actually show them.
function publishingCard(c){const k=c.connection||{},v=k.vercel,account=state.vercel||{};
  if(k.provider==='vercel'&&v){const checks=v.readiness?.checks||[];return `<section class="card publishing-card"><div class="card-head"><div><span class="eyebrow">WHERE ARTICLES GO LIVE</span><h2>${esc(v.domain)}</h2></div><span class="badge ${v.readiness?.ready?'success':'warning'}">${v.readiness?.ready?'Ready to publish':'Needs a blog section'}</span></div>
    <p class="muted">Vercel project <strong>${esc(v.name)}</strong> · GitHub <strong>${esc(v.repo)}</strong> (${esc(v.branch)}) · articles at <strong>${esc(String(k.public_url_template||'').replace('https://',''))}</strong></p>
    <ul class="readiness-list">${[{ok:true,label:'Vercel project connected'},{ok:true,label:'RankMe has its own copy of the repository'},...checks].map(x=>`<li class="${x.ok?'ok':'todo'}"><span aria-hidden="true">${x.ok?'✓':'!'}</span><div>${esc(x.label)}${x.detail?`<small>${esc(x.detail)}</small>`:''}</div></li>`).join('')}</ul>
    <p class="hint">${k.auto_publish?'Reviewed articles go live automatically on the weekly schedule.':'Reviewed articles wait in “Ready to publish” until you click Publish.'} Checked ${esc(time(v.checked_at))}.</p>
    <div class="actions section"><button class="button small" data-action="vercel-check" data-id="${esc(c.id)}">Check again</button><button class="button small" data-action="vercel-link" data-id="${esc(c.id)}">Change project</button><button class="button small" data-action="toggle-auto-publish" data-id="${esc(c.id)}">${k.auto_publish?'Wait for my approval instead':'Publish automatically after review'}</button><button class="button ghost small" data-action="vercel-unlink" data-id="${esc(c.id)}">Disconnect</button></div></section>`;}
  const other=k.project_path?`<p class="hint">Currently publishing to a local folder: ${esc(k.project_path)}.</p>`:'';
  return `<section class="card publishing-card"><div class="card-head"><div><span class="eyebrow">WHERE ARTICLES GO LIVE</span><h2>Connect this website</h2></div><span class="badge neutral">Not connected</span></div><p class="muted">Choose the Vercel project that serves ${esc(new URL(c.url).hostname)}. RankMe sets up the repository, branch, and article address for you.</p>${other}<div class="actions section">${hosted?'<p class="hint">Connect websites in RankMe on your Mac.</p>':account.connected?`<button class="button primary" data-action="vercel-link" data-id="${esc(c.id)}">Choose Vercel project</button>`:'<button class="button primary" data-nav="settings">Connect Vercel in Settings</button>'}${hosted?'':`<button class="button ghost small" data-action="connection" data-id="${esc(c.id)}">Use a local folder instead</button>`}</div></section>`;}
let vercelProjects=[];
async function vercelLinkModal(c){modal('Choose the Vercel project',`<p class="muted">Loading your Vercel projects…</p>`);let projects=[];try{projects=(await api('/api/vercel/projects')).projects||[];}catch(error){if($('#modal').open)$('#dialog-error').textContent=error.message;return;}if(!$('#modal').open)return;
  const host=new URL(c.url).hostname.replace(/^www\./,''),current=c.connection?.vercel?.project_id;
  const score=p=>p.id===current?3:p.domains.some(d=>d.replace(/^www\./,'')===host)?2:p.repo?1:0;
  projects.sort((a,b)=>score(b)-score(a)||a.name.localeCompare(b.name));
  vercelProjects=projects;
  modal('Choose the Vercel project',`<form id="vercel-link-form" data-id="${esc(c.id)}"><p class="muted">Pick the project that serves <strong>${esc(host)}</strong>. Projects matching this domain are listed first.</p><div class="field section"><label for="vercel-project">Vercel project</label><select id="vercel-project" name="project" required>${projects.map(p=>`<option value="${esc(p.team_id+'|'+p.id)}" ${!p.repo?'disabled':''}>${esc(p.name)}${p.domains[0]?' · '+esc(p.domains[0]):''}${p.repo?'':' · not linked to GitHub'}</option>`).join('')}</select><small class="hint" id="vercel-project-detail"></small></div><div class="form-grid"><div class="field"><label for="vercel-domain">Website address</label><select id="vercel-domain" name="domain"></select></div>${field('blog_path','Blog path','/blog','text','Articles will live at address/blog/article-name.')}</div><details class="disclosure"><summary>Advanced</summary><div class="disclosure-body">${field('content_dir','Article folder in the repository','','text','Leave empty to detect it, or use content/blog.')}</div></details><div class="notice section">RankMe makes its own copy of the GitHub repository on this Mac and never touches your working folders. It pushes one commit per article to the production branch, which Vercel deploys.</div>${formActions('Connect project')}</form>`);vercelProjectChanged();}
function vercelProjectChanged(){const select=$('#vercel-project');if(!select)return;const p=vercelProjects.find(x=>x.team_id+'|'+x.id===select.value);if(!p)return;$('#vercel-domain').innerHTML=p.domains.map(d=>`<option>${esc(d)}</option>`).join('')||'<option value="">No domain</option>';$('#vercel-project-detail').textContent=p.repo?`GitHub ${p.repo} · deploys from ${p.branch}${p.framework?' · '+p.framework:''}`:'This project is not linked to GitHub, so RankMe cannot publish to it.';}
const metric=(value,digits=0)=>typeof value==='number'&&Number.isFinite(value)?value.toLocaleString(undefined,{maximumFractionDigits:digits}):'—';
function seoMetrics(current,previous){return `<div class="stats">${[['Clicks','clicks',0,false],['Impressions','impressions',0,false],['Click-through rate','ctr',2,true],['Average position','position',1,false]].map(([title,key,digits,percentage])=>{const value=key==='position'&&!(current?.impressions>0)?null:current?.[key],prior=key==='position'&&!(previous?.impressions>0)?null:previous?.[key],formatted=typeof value==='number'?(metric(percentage?value*100:value,digits)+(percentage?'%':'')):'—';return `<div class="card stat"><div class="stat-label">${title}</div><div class="stat-value">${formatted}</div><div class="stat-note">Previous period: ${typeof prior==='number'?metric(percentage?prior*100:prior,digits)+(percentage?'%':''):'unavailable'}</div></div>`;}).join('')}</div>`;}
function searchTable(rows,kind){return rows?.length?`<div class="table-wrap"><table><thead><tr><th>${kind==='queries'?'SEARCH QUERY':'PAGE'}</th><th>CLICKS</th><th>IMPRESSIONS</th><th>CTR</th><th>POSITION</th></tr></thead><tbody>${rows.slice(0,25).map(row=>{const key=row.keys?.[0]||row.query||row.page||row.url||'';return `<tr><td class="seo-row-label">${kind==='pages'?`<a href="${esc(safeURL(key))}" target="_blank" rel="noopener noreferrer">${esc(key)}</a>`:esc(key)}</td><td>${metric(row.clicks)}</td><td>${metric(row.impressions)}</td><td>${typeof row.ctr==='number'?metric(row.ctr*100,2)+'%':'—'}</td><td>${row.impressions>0?metric(row.position,1):'—'}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="muted">No rows returned for this period. Missing data is not treated as zero.</p>';}
function seoWorkspace(c){const snapshots=Array.isArray(state.seo)?state.seo:[],snapshot=snapshots.filter(s=>s.client_id===c.id).sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||'')))[0];const connected=!!state.google?.connected,configured=!!c.seo_connection?.site_url,running=state.jobs.find(j=>j.client_id===c.id&&['queued','running'].includes(j.status));const previousProperty=!!snapshot&&(snapshot.site_url!==c.seo_connection?.site_url||String(snapshot.ga4_property||'').replace(/^properties\//,'')!==String(c.seo_connection?.ga4_property||'').replace(/^properties\//,''));const sc=snapshot?.search_console,backlinks=(state.backlinks||[]).filter(link=>link.client_id===c.id);return `<div class="seo-workspace"><section class="card"><div class="card-head"><div><span class="eyebrow">SEARCH PERFORMANCE</span><h2>See what your content earns.</h2></div><div class="actions">${connected&&!hosted?`<button class="button small" data-action="seo-properties" data-id="${esc(c.id)}">${configured?'Change properties':'Choose properties'}</button>${configured?`<button class="button primary small" data-action="seo-sync" data-id="${esc(c.id)}" ${running?'disabled':''}>Sync Google data</button>`:''}`:''}</div></div><p class="muted">${configured?esc(c.seo_connection.site_url):'Connect Google and select this client’s Search Console property to track real search performance.'}</p>${c.seo_error?`<div class="notice error section">${esc(c.seo_error)}</div>`:''}${configured?`<p class="hint">${c.seo_connection.auto_sync!==false?'Daily Google sync is on.':'Automatic Google sync is off.'} Background sync and weekly link checks run while RankMe is open; workspace pause applies.</p>`:''}${snapshot?`<p class="hint">Last sync: ${time(snapshot.updated_at)}${snapshot.periods?.current?' · '+esc(snapshot.periods.current.start)+' to '+esc(snapshot.periods.current.end):''}</p>`:''}${running?`<p class="hint"><span class="spinner"></span>${esc(running.stage||'Work is queued for this client.')} ${stopButton(running)}</p>`:''}</section>${!connected?googleCard():`<details class="card disclosure"><summary>Google account settings</summary><div class="disclosure-body">${googleCard()}</div></details>`}${previousProperty?`<div class="notice warning"><strong>Previous property report</strong><br>The figures below belong to ${esc(snapshot.site_url||'the previously selected Search Console property')}${snapshot.ga4_property?' and Analytics '+esc(snapshot.ga4_property):''}, not the current property selection. Sync Google data to replace this report.</div>`:''}${snapshot?.issues?.length?`<div class="notice warning">${snapshot.issues.map(issue=>esc(typeof issue==='string'?issue:JSON.stringify(issue))).join('<br>')}</div>`:''}${snapshot?`${seoMetrics(sc?.current?.totals,sc?.previous?.totals)}${snapshot.analytics?`<section class="card"><div class="card-head"><h2>Organic search outcomes</h2><span class="muted">Google Analytics</span></div><div class="seo-outcomes"><div><span class="eyebrow">ORGANIC SESSIONS</span><strong>${metric(snapshot.analytics.current?.organic_sessions)}</strong><p class="hint">Previous: ${metric(snapshot.analytics.previous?.organic_sessions)}</p></div><div><span class="eyebrow">KEY EVENTS</span><strong>${metric(snapshot.analytics.current?.key_events)}</strong><p class="hint">Previous: ${metric(snapshot.analytics.previous?.key_events)}</p></div></div><p class="hint">Key events reflect the events configured in this Google Analytics property. They are not necessarily leads or sales. Analytics uses the property’s reporting timezone and may apply privacy thresholds; totals can differ from Search Console.</p></section>`:''}<section class="card"><h2>What to improve next</h2>${snapshot.recommendations?.length?`<div class="seo-recommendations">${snapshot.recommendations.map(item=>`<div class="seo-recommendation">${typeof item==='string'?`<p>${esc(item)}</p>`:`<h3>${esc(item.title||item.action||'Recommendation')}</h3><p>${esc(item.reason||item.description||item.message||'')}</p>${item.evidence?`<p class="hint">${esc(typeof item.evidence==='string'?item.evidence:JSON.stringify(item.evidence))}</p>`:''}`}</div>`).join('')}</div>`:'<p class="muted section">No recommendations returned yet. More search data may be needed.</p>'}</section><section class="card"><div class="card-head"><h2>Search queries</h2><span class="muted">Current period · up to 25 rows</span></div>${searchTable(sc?.current?.queries,'queries')}${sc?.limited?'<p class="hint">Search Console limits returned rows and may omit anonymized queries. Rows may not sum to totals.</p>':''}</section><section class="card"><div class="card-head"><h2>Pages in search</h2><span class="muted">Current period · up to 25 rows</span></div>${searchTable(sc?.current?.pages,'pages')}</section>`:''}<section class="card"><div class="card-head"><div><span class="eyebrow">EARNED LINKS</span><h2>Backlink opportunities</h2></div><div class="actions"><button class="button small" data-action="backlink-track" data-id="${esc(c.id)}">Track a link</button><button class="button small" data-action="backlinks-discover" data-id="${esc(c.id)}" ${!c.confirmed||running?'disabled':''}>Find opportunities</button></div></div><p class="muted">Research relevant websites, review outreach drafts, and check links. RankMe does not send messages or arrange link exchanges.</p>${backlinks.length?`<div class="backlink-list">${backlinks.map(link=>`<div class="backlink-row"><div class="grow"><h3>${esc(link.title||link.name||link.source_url||link.url||'Link opportunity')}</h3><p class="hint">${esc(link.reason||link.relevance||'')}</p><a class="hint" href="${esc(safeURL(link.source_url||link.url))}" target="_blank" rel="noopener noreferrer">${esc(link.source_url||link.url||'')}</a></div><div class="backlink-statuses"><span class="hint">Tracking</span>${badge(link.status==='live'?'tracked':link.status||'prospect')}<span class="hint">Latest check</span><span class="badge ${link.verification?.live?'success':link.verification?.status==='error'?'warning':'neutral'}">${link.verification?.live?'Link found':link.verification?.status==='missing'?'No link found':link.verification?.status==='error'?'Check failed':'Not checked'}</span></div><button class="button small" data-action="backlink-open" data-id="${esc(link.id)}">Review</button></div>`).join('')}</div>`:`<div class="seo-empty"><p class="muted">${c.confirmed?'No opportunities yet. Find opportunities to start research, or track a link you already know.':'No opportunities yet. Confirm the business profile, then start research.'}</p></div>`}</section></div>`;}
function googleSetup(){modal('Set up Google access',`<p class="muted">Create your own Google OAuth credentials once. Use the same connection across client properties you have access to.</p><ol class="detail-list section"><li>Open <a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">Google Cloud Console</a> and choose or create a project.</li><li>Enable the Search Console API. For optional Analytics reporting, also enable the Google Analytics Data API and Google Analytics Admin API.</li><li>Configure the OAuth consent screen. If the app is in testing, add your Google account as a test user.</li><li>Create an OAuth client with application type <strong>Desktop app</strong>. Copy its client ID and client secret below.</li></ol><form id="google-configure-form" class="section">${field('client_id','OAuth client ID','','text','This identifies your Google application, not a RankMe client.')}${field('client_secret','OAuth client secret','','password','Stored locally for this Google connection. Never enter your Google password.')}${formActions('Save Google configuration')}</form>`);$('#f-client_id').required=true;$('#f-client_secret').required=true;$('#f-client_secret').autocomplete='off';}
async function seoProperties(c){modal('Choose Google properties',`<p class="muted">Loading available properties…</p>`);let properties={search_console:[],analytics:[],issues:[]};try{if(state.google?.connected)properties=await api('/api/google/properties');}catch(error){properties.issues=[error.message];}if(!$('#modal').open)return;const sc=properties.search_console||[],ga=properties.analytics||[],connection=c.seo_connection||{};modal('Choose Google properties',`<form id="seo-properties-form" data-id="${esc(c.id)}"><p class="muted">Use the properties for ${esc(c.name||c.url)}. Search Console is required for search reports; Google Analytics is optional.</p>${!state.google?.connected?'<div class="notice warning section">Google is not connected. You can save property identifiers now and sign in afterward.</div>':''}${properties.issues?.length?`<div class="notice warning section">${properties.issues.map(x=>esc(typeof x==='string'?x:JSON.stringify(x))).join('<br>')}</div>`:''}<div class="field section"><label for="seo-site">Search Console property</label><input id="seo-site" name="site_url" list="sc-properties" value="${esc(connection.site_url||'')}" required placeholder="sc-domain:example.com or https://example.com/"><datalist id="sc-properties">${sc.map(item=>{const value=typeof item==='string'?item:item.siteUrl;return `<option value="${esc(value)}">${esc(item.permissionLevel||'')}</option>`;}).join('')}</datalist><small class="hint">Copy the exact property name. Domain properties begin with sc-domain:.</small></div><div class="field"><label for="seo-ga">Google Analytics property (optional)</label><input id="seo-ga" name="ga4_property" list="ga-properties" value="${esc(connection.ga4_property||'')}" placeholder="properties/123456789"><datalist id="ga-properties">${ga.map(item=>{const value=typeof item==='string'?item:item.property;return `<option value="${esc(value)}">${esc(item.displayName||'')} ${esc(item.account||'')}</option>`;}).join('')}</datalist><small class="hint">Use the numeric property ID or properties/ID, not the G- measurement ID.</small></div><label class="check-label"><input type="checkbox" name="auto_sync" ${connection.auto_sync!==false?'checked':''}>Sync Google data automatically each day while RankMe is running</label>${formActions('Save properties')}</form>`);}
function backlinkModal(id){const link=(state.backlinks||[]).find(item=>item.id===id);if(!link)return;const target=link.target_url||link.verification?.target_url||client(link.client_id)?.url||'';const draft=link.outreach_draft||link.draft||'',draftText=typeof draft==='string'?draft:JSON.stringify(draft,null,2);modal('Review link opportunity',`<div class="notice">Draft only. Review the website and personalise any outreach yourself. RankMe does not send it.</div><h3>${esc(link.title||link.name||'Link opportunity')}</h3><p class="muted section">${esc(link.reason||link.relevance||'')}</p><p class="source"><strong>Source:</strong> <a href="${esc(safeURL(link.source_url||link.url))}" target="_blank" rel="noopener noreferrer">${esc(link.source_url||link.url||'Not provided')}</a><br><strong>Target:</strong> <a href="${esc(safeURL(target))}" target="_blank" rel="noopener noreferrer">${esc(target||'Not selected')}</a></p>${link.evidence?`<div class="source"><strong>Research evidence</strong><p>${esc(link.evidence.quote||link.evidence.message||'No supporting passage recorded.')}</p><small>${link.evidence.verified?'Source checked':'Source needs review'}${link.evidence.checked_at?' · '+time(link.evidence.checked_at):''}</small></div>`:''}${link.verification?`<div class="notice section"><strong>${link.verification.live?'Live link found':esc(label(link.verification.status||'not_checked'))}</strong><p>${esc(link.verification.message||'')}</p>${link.verification.checked_at?`<small>Checked ${time(link.verification.checked_at)}</small>`:''}${link.verification.links?.length?`<ul class="detail-list">${link.verification.links.map(found=>`<li>${esc(found.anchor||found.url)}${found.nofollow?' · nofollow':''}${found.sponsored?' · sponsored':''}${found.ugc?' · user-generated':''}</li>`).join('')}</ul>`:''}</div>`:''}${draftText?`<div class="field section"><label for="backlink-draft">Outreach draft</label><textarea id="backlink-draft" readonly rows="8">${esc(draftText)}</textarea><button class="button small section" data-action="copy-draft">Copy draft</button></div>`:'<p class="muted section">No outreach draft recorded.</p>'}<form id="backlink-form" data-id="${esc(id)}"><div class="field section"><label for="backlink-status">Tracking status</label><select name="status" id="backlink-status">${[...new Set([link.status||'draft','prospect','needs_review','draft','contacted','dismissed'])].map(status=>`<option value="${esc(status)}" ${status===link.status?'selected':''}>${esc(label(status))}</option>`).join('')}</select><small class="hint">Use Check for link to verify a live backlink. Mark contacted only after you send outreach yourself.</small></div>${field('notes','Your notes',link.notes||'','textarea')}<div class="form-actions"><button type="button" class="button" data-action="backlink-check" data-id="${esc(id)}">Check for link</button><button class="button primary">Save tracking</button></div></form>`,true);}

function credentialListHTML(){if(!credentialsLoaded)return '<p class="muted">Loading passkeys…</p>';if(!credentialRows.length)return '<p class="muted">No passkeys found. Unlock again if this looks wrong.</p>';return credentialRows.map(item=>`<div class="passkey-row"><div><strong>${esc(item.name||'Passkey')}</strong><small>Added ${esc(date(typeof item.created_at==='number'?item.created_at*1000:item.created_at))}</small></div><button class="button danger small" type="button" data-action="passkey-remove" data-id="${esc(item.id)}" ${credentialRows.length===1?'disabled title="Keep at least one passkey"':''}>Remove</button></div>`).join('');}
async function loadCredentials(){if(!authenticated||credentialsLoaded||credentialsLoading)return;credentialsLoading=true;try{const result=await RankMeAuth.credentials();if(!authenticated)return;credentialRows=Array.isArray(result.credentials)?result.credentials:[];credentialsLoaded=true;const list=$('#passkey-list');if(list)list.innerHTML=credentialListHTML();}catch(error){const list=$('#passkey-list');if(list&&authenticated)list.textContent=RankMeAuth.errorMessage(error);}finally{credentialsLoading=false;}}
function cloudSettings(){const settings=state.settings||{};return heading('Workspace settings','Your passkeys and cloud connection.')+`<div class="grid-two"><div class="stack"><section class="card"><h3>Workspace passkeys</h3><p class="muted section">Add a backup passkey so you can unlock this workspace if one device is unavailable. A fresh verification is required.</p><div id="passkey-list" class="section">${credentialListHTML()}</div><form id="passkey-add-form" class="section"><div class="field"><label for="passkey-name">Name for new passkey</label><input id="passkey-name" name="name" maxlength="80" placeholder="e.g. Backup security key" required></div><button class="button primary small" type="submit">Add backup passkey</button></form></section>${googleCard()}${vercelCard()}</div><div class="stack"><form id="cloud-settings-form" class="card"><h3>Automation settings</h3><p class="muted section">These settings are applied by your Mac when it connects.</p><div class="field"><label for="cloud-model">Model override</label><input id="cloud-model" name="model" value="${esc(settings.model||'')}" placeholder="Use Codex default"></div><div class="field"><label for="cloud-pages">Inspection page limit</label><input id="cloud-pages" name="max_pages" type="number" min="1" max="80" value="${esc(settings.max_pages||24)}"></div><label class="check-label"><input type="checkbox" name="paused" ${settings.paused?'checked':''}>Pause scheduled automation</label><div class="form-actions"><button class="button primary" type="submit">Save settings</button></div></form><section class="card"><h3>Mac worker</h3><p class="muted section">RankMe uses your Mac to research, write, review, and publish. Queued changes run when it connects.</p>${cloudStatus()}<p class="hint">Manage Codex, publishing folders, Google access, and local automation in RankMe on your Mac.</p></section><section class="card"><h3>Cloud backup</h3><p class="muted section">Download the latest synced client profiles, articles, and activity.</p><a class="button small" href="/api/backup" download>Download cloud snapshot</a></section></div></div>`;}
function settings(){if(hosted)return cloudSettings();const s=state.settings||{};return heading('Workspace settings','Your computer. Your clients. Your controls.')+`<div class="grid-two"><form id="settings-form" class="card"><h2>Codex connection</h2><p class="subheading">Use your ChatGPT subscription through the local Codex CLI.</p><div class="divider"></div><div class="field"><label for="codex-path">Codex executable</label><input id="codex-path" name="codex_path" value="${esc(s.codex_path||'codex')}"><small class="hint">Use “codex” or the absolute path to the installed executable.</small></div><div class="field"><label for="model">Model override</label><input id="model" name="model" value="${esc(s.model||'')}" placeholder="Use Codex default"><small class="hint">Leave empty to use the Codex CLI default model.</small></div><div class="field"><label for="max-pages">Inspection page limit</label><input id="max-pages" name="max_pages" type="number" min="1" max="80" step="1" value="${esc(s.max_pages||24)}"><small class="hint">Inspect up to 1–80 public pages per website. Larger inspections take longer.</small></div><label class="check-label"><input type="checkbox" name="paused" ${s.paused?'checked':''}>Pause all scheduled automation</label><div class="form-actions"><button type="button" class="button" data-action="check-codex">Check connection</button><button class="button primary">Save settings</button></div></form><div class="stack"><section class="card"><h3>Workspace passkeys</h3><p class="muted section">Add a backup passkey so you can still unlock this workspace if one device is unavailable. Adding or removing a passkey requires a fresh verification.</p><div id="passkey-list" class="section">${credentialListHTML()}</div><form id="passkey-add-form" class="section"><div class="field"><label for="passkey-name">Name for new passkey</label><input id="passkey-name" name="name" maxlength="80" placeholder="e.g. Backup security key" required></div><button class="button primary small" type="submit">Add backup passkey</button></form></section>${health()}${googleCard()}${vercelCard()}<section class="card"><h3>Local data & backup</h3><p class="connection-info section">Client profiles, articles, and job history stay in your local workspace. AI tasks send necessary context to Codex. Website research and publishing require internet.</p><a class="button small section" href="/api/backup" download>Download backup</a><p class="hint">Backup may contain private client details. Store it securely.</p></section><section class="card"><h3>First connection</h3><p class="connection-info section">Install Codex CLI, then run <code>codex login</code> in Terminal and sign in with ChatGPT. Return here and check the connection.</p><p class="hint">Codex subscription quotas apply and are shared with your other Codex work. Your computer must stay awake with RankMe running for scheduled jobs. RankMe does not require an OpenAI API key.</p></section></div></div>`;}
function render(){if(!authenticated)return;const names={overview:'Overview',clients:'Clients',content:'Content library',activity:'Activity',settings:'Settings',client:'Client workspace'};$('#breadcrumb').innerHTML=`Workspace <b>/</b> ${names[view]||'Overview'}`;document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===(view==='client'?'clients':view)));let html;if(view==='client')html=detail(client(selected));else if(view==='clients')html=heading('Client websites','A separate business profile and content strategy for every website.')+`<section class="card"><div class="client-list">${state.clients.length?state.clients.map(clientRow).join(''):'<div class="empty"><div class="empty-symbol">▦</div><h2>Your first client starts with a URL.</h2><p>RankMe will inspect the website before asking what to write about.</p><button class="button primary" data-action="add">＋ Add website</button></div>'}</div></section>`;else if(view==='content'){const withArticles=state.clients.filter(c=>state.articles.some(a=>a.client_id===c.id));if(articleClientFilter&&!client(articleClientFilter))articleClientFilter='';html=heading('Content library','Every article across your websites: what is written, what is waiting, and what is live.',withArticles.length>1?`<div class="field compact-field"><label for="article-client-filter">Website</label><select id="article-client-filter"><option value="">All websites</option>${withArticles.map(c=>`<option value="${esc(c.id)}" ${articleClientFilter===c.id?'selected':''}>${esc(c.name||c.url)}</option>`).join('')}</select></div>`:'')+`<section class="card">${articleClientFilter?scheduleSummary(client(articleClientFilter)):''}${pipeline(state.articles.filter(a=>!articleClientFilter||a.client_id===articleClientFilter),{showClient:!articleClientFilter})}</section>`;}else if(view==='activity')html=heading('Workspace activity','A clear record of research, reviews, publishing, and exceptions.')+`<section class="card"><div class="card-head"><h2>Jobs</h2><span class="muted">${state.jobs.length} total</span></div>${state.jobs.length?state.jobs.slice(0,30).map(j=>`<div class="client-row" style="margin-bottom:10px"><div class="grow"><h3>${esc(label(j.kind))}</h3><small>${esc(client(j.client_id)?.name||'Workspace')} · ${esc(j.stage||'')} · ${time(j.created_at)}</small>${j.error?`<p class="muted" style="color:var(--red)">${esc(j.error)}</p>`:''}</div>${badge(j.status)}${j.status==='failed'?`<button class="button small" data-action="retry" data-id="${j.id}">Retry</button><button class="button ghost small" data-action="dismiss-job" data-id="${esc(j.id)}">Dismiss</button>`:''}${stopButton(j)}</div>`).join(''):'<p class="muted">No jobs yet. Add a website to start.</p>'}</section><section class="card section"><h2>Event history</h2>${eventRows(state.events.slice(0,80))}</section>`;else if(view==='settings')html=settings();else html=overview();$('#page').innerHTML=cloudStatus()+html;if(view==='settings')loadCredentials();}
function navigate(next,id){if(selected!==id)clientTab='content';if(next!==view||id!==selected)articleFilter=null;view=next;selected=id||null;location.hash=next+(id?'/'+id:'');render();}
// Hash routes: #view, #client/<id>, or #client/<id>/<tab>. A client without an explicit tab opens on Content.
function applyRoute(){const [next,id,tab]=location.hash.slice(1).split('/');view=['overview','clients','content','activity','settings','client'].includes(next)?next:'overview';selected=view==='client'?id||null:null;clientTab=['content','seo','visibility'].includes(tab)?tab:'content';}
function modal(title,html,wide=false){activeArticleDialog=null;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html+'<div class="dialog-error" id="dialog-error" role="alert"></div>';$('#modal').classList.toggle('wide',wide);if(!$('#modal').open)$('#modal').showModal();}
function close(){activeArticleDialog=null;$('#modal').close();}
function field(name,title,value='',type='text',hint=''){return `<div class="field"><label for="f-${name}">${esc(title)}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}">${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}">`}${hint?`<small class="hint">${esc(hint)}</small>`:''}</div>`;}
const formActions=(title='Save')=>`<div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button primary" type="submit">${title}</button></div>`;
function addModal(){modal('Add a client website',`<p class="muted" style="margin-bottom:22px">Start with the public website. RankMe will inspect accessible public pages and build an evidence-based business profile.</p><form id="add-form">${field('url','Website URL','','url','Example: https://yourclient.com')}${field('name','Client name (optional)')}<div class="notice">Inspection runs in the background using Codex. The crawler reads public HTML within its page limit; it does not render JavaScript or access private pages. Review the profile before choosing a subject.</div>${formActions('Inspect website')}</form>`);$('#f-url').required=true;$('#f-url').focus();}
function profileModal(c){const p=c.profile||{};modal('Review business profile',`<form id="profile-form" data-id="${c.id}"><div class="notice">Check the details below and correct anything inaccurate. Confirming tells RankMe to use this profile when planning and writing. Nothing is published. Missing information may stay unknown.</div>${field('name','Business name',p.name||c.name)}${field('summary','Business summary',p.summary,'textarea')}${field('audience','Target audience',p.audience,'textarea')}<div class="form-grid">${field('services','Services / products',(p.services||[]).join('\n'),'textarea','One per line.')}${field('locations','Locations',(p.locations||[]).join('\n'),'textarea','One per line.')}${field('tone','Brand voice',p.tone,'textarea')}${field('language','Language',p.language,'textarea')}</div><p class="hint section">Cover images are set up separately under <strong>Cover style</strong> on this website’s page.</p><details class="disclosure"><summary>Missing information & research evidence</summary><div class="disclosure-body">${field('unknowns','Unresolved questions',(p.unknowns||[]).join('\n'),'textarea','One per line. Leave genuine unknowns visible.')}<h3>Evidence collected</h3><div style="max-height:190px;overflow:auto">${(p.facts||[]).map(f=>`<div class="source">${esc(f.claim)}<br><a target="_blank" rel="noopener noreferrer" href="${esc(safeURL(f.source))}">${esc(f.source)}</a></div>`).join('')||'<p class="muted">No evidence recorded.</p>'}</div></div></details>${formActions('Confirm business profile')}</form>`);}
function subjectModal(c){modal('Which subject should we tackle?',`<form id="subject-form" data-id="${c.id}"><p class="muted" style="margin-bottom:20px">Choose a suggested direction or enter your own. RankMe researches it and builds a twelve-week content plan.</p>${(c.profile?.suggested_subjects||[]).map((s,i)=>`<label class="subject-option"><input type="radio" name="suggested" value="${esc(s.title)}">${esc(s.title)}<small>${esc(s.reason)}</small></label>`).join('')}${field('subject','Your subject',c.subject||'','text','Be specific: the customer problem, service, or topic to focus on.')}${formActions('Research & build plan')}</form>`);}
function connectionModal(c){if(hosted){modal('Publishing connection', '<p class="muted">Set up project folders and publishing commands in RankMe on your Mac.</p>');return;}const k=c.connection||{};modal('Connect publishing',`<form id="connection-form" data-id="${c.id}"><div class="notice">Start with local export. Enable Git deployment only after validating this website’s content format and commands.</div>${field('project_path','Website project folder',k.project_path||'','text','Absolute path to this client’s code project.')}${field('content_dir','Article folder',k.content_dir||'content/articles','text','Relative to the website project folder.')}${field('image_dir','Cover image folder',k.image_dir||'public/images/articles','text','Relative to the project. Must be served by your website.')}${field('image_url_prefix','Public image path',k.image_url_prefix||'/images/articles','text','URL path corresponding to that folder.')}<div class="form-grid"><div class="field"><label for="f-format">Article format</label><select name="format" id="f-format">${['md','mdx','json'].map(f=>`<option ${k.format===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="field"><label for="f-mode">Publishing mode</label><select name="mode" id="f-mode"><option value="export" ${k.mode!=='git'?'selected':''}>Local export</option><option value="git" ${k.mode==='git'?'selected':''}>Git deployment</option></select></div>${field('branch','Git branch',k.branch||'main')}${field('remote','Git remote',k.remote||'origin')}</div>${field('build_command','Build command (JSON argument list)',JSON.stringify(k.build_command||[]),'text','Example: ["npm", "run", "build"]. No shell operators.')}${field('deploy_command','Deployment command (JSON argument list)',JSON.stringify(k.deploy_command||[]),'text','Optional. Example: ["vercel", "--prod"]. Runs in the project folder.')}${field('public_url_template','Published URL pattern',k.public_url_template||'','url','Example: https://client.com/blog/{slug}')}<label class="check-label"><input name="auto_publish" type="checkbox" ${k.auto_publish?'checked':''}>Enable automatic publishing after article checks pass. Git mode may commit, push, and deploy to the live website.</label><div id="connection-result" class="hint section"></div><div class="form-actions"><button type="button" class="button" data-action="test-connection">Check folder</button><button class="button primary">Save connection</button></div></form>`);}
function markdown(text){
  const lines=String(text||'').split('\n');let out='',code=false,list='';
  function inline(s){
    const tokens=[];
    let result=esc(s).replace(/\[([^\]]+)\]\(([^\s)]+)\)/g,(_,t,u)=>{const key='\u0000'+tokens.length+'\u0000';tokens.push(`<a href="${esc(safeURL(u.replaceAll('&amp;','&')))}" target="_blank" rel="noopener noreferrer">${t}</a>`);return key;}).replace(/`([^`]+)`/g,(_,content)=>{const key='\u0000'+tokens.length+'\u0000';tokens.push('<code>'+content+'</code>');return key;}).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
    return result.replace(/\u0000(\d+)\u0000/g,(_,i)=>tokens[Number(i)]||'');
  }
  function cells(line){return line.trim().replace(/^\|/,'').replace(/\|$/,'').replace(/\\\|/g,'\u0001').split('|').map(cell=>cell.trim().replaceAll('\u0001','|'));}
  function closeList(){if(list){out+='</'+list+'>';list='';}}
  for(let i=0;i<lines.length;i++){
    const line=lines[i];
    if(line.startsWith('```')){closeList();out+=code?'</code></pre>':'<pre><code>';code=!code;continue;}
    if(code){out+=esc(line)+'\n';continue;}
    const next=lines[i+1]||'';
    if(line.includes('|')&&next.includes('|')&&cells(next).every(cell=>/^:?-{3,}:?$/.test(cell))){
      closeList();const headers=cells(line);out+='<div class="article-table"><table><thead><tr>'+headers.map(cell=>'<th>'+inline(cell)+'</th>').join('')+'</tr></thead><tbody>';i++;
      while(i+1<lines.length&&lines[i+1].trim()&&lines[i+1].includes('|')&&!lines[i+1].startsWith('```')){i++;const row=cells(lines[i]);out+='<tr>'+headers.map((_,column)=>'<td>'+inline(row[column]||'')+'</td>').join('')+'</tr>';}
      out+='</tbody></table></div>';continue;
    }
    const unordered=line.match(/^\s*[-*] (.*)/),ordered=line.match(/^\s*(\d+)[.)] (.*)/);
    if(unordered||ordered){const kind=ordered?'ol':'ul';if(list!==kind){closeList();out+='<'+kind+(ordered?' start="'+Number(ordered[1])+'"':'')+'>';list=kind;}out+='<li>'+inline(ordered?ordered[2]:unordered[1])+'</li>';continue;}
    closeList();const h=line.match(/^(#{1,6}) (.*)/);
    if(h)out+=`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;
    else if(line.startsWith('> '))out+='<blockquote>'+inline(line.slice(2))+'</blockquote>';
    else if(line.trim())out+='<p>'+inline(line)+'</p>';
  }
  closeList();if(code)out+='</code></pre>';return out;
}

function parseImageBrand(colors,style){const parsed=String(colors||'').split(',').map(color=>color.trim()).filter(Boolean);if(parsed.some(color=>!/^#[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(color)))throw Error('Enter brand colors as comma-separated hex codes, such as #183A5C, #C6A976.');return {colors:[...new Set(parsed.map(color=>color.toUpperCase()))],style:String(style||'').trim()};}
function coverPreview(a){if(hosted&&a.cover?.path)return `<div class="cover-pending">Cover image available in the Mac workspace.</div>`;if(a.cover?.path)return `<figure class="article-cover"><img src="/api/articles/${encodeURIComponent(a.id)}/cover?v=${encodeURIComponent(a.cover.sha256||a.updated_at||'')}" alt="${esc(a.cover.alt||'Article cover image')}" loading="lazy"><figcaption>${esc(a.cover.alt||'AI-generated editorial cover')}${(a.cover_stale||a.cover.review?.passed===false)?'<span class="badge warning">Cover needs review</span>':''}</figcaption></figure>`;if(a.status==='generating_cover')return '<div class="notice"><span class="spinner"></span>Creating and reviewing a cover in this website’s house style.</div>';return '<div class="cover-pending"><span class="eyebrow">ARTICLE COVER</span>A cover in this website’s house style will be generated and reviewed before publishing.</div>';}
function referenceButton(a){const c=client(a.client_id);if(hosted||!c||!a.cover?.review?.passed||a.cover_stale||(a.cover.mode||'illustration_3d')!==coverMode(c))return '';const used=(c.image_brand?.references||[]).some(r=>r.article_id===a.id);return `<button class="button small" data-action="style-reference" data-id="${esc(a.id)}" data-use="${used?'':'1'}">${used?'Remove from style references':'Use as style reference'}</button>`;}
function removeCoverButton(a){if(!a.cover||a.publish_started||['published','exported','verification_pending','refreshed'].includes(a.status))return '';return `<button class="button danger small" data-action="remove-cover" data-id="${esc(a.id)}">Delete cover</button>`;}
function coverReview(a){const review=a.cover_stale?{passed:false,summary:'The article or brand changed. Generate a new cover before publishing.',issues:[]}:a.cover?.review;return `<h3 class="section">Cover image review</h3><div class="actions">${referenceButton(a)}${removeCoverButton(a)}</div>${a.cover?.alt?`<p class="hint"><strong>Alt text:</strong> ${esc(a.cover.alt)}</p>`:''}<div class="notice ${review?.passed?'':'warning'} section">${esc(review?.summary||(review?.passed?'Cover passed review.':a.cover?'Cover review has not passed. Publishing stays on hold until the cover passes.':'No cover generated yet. Publishing requires a reviewed cover.'))}</div>${review?.issues?.length?`<ul class="detail-list">${review.issues.map(issue=>`<li>${esc(typeof issue==='string'?issue:JSON.stringify(issue))}</li>`).join('')}</ul>`:''}`;}
function articleModal(id,tab='preview'){const a=state.articles.find(x=>x.id===id);if(!a)return;const immutable=a.publish_started||['published','exported','verification_pending'].includes(a.status);let body;if(tab==='edit'&&immutable)body='<div class="notice">Published content is preserved. Edit the article in its website project to make changes.</div>';else if(tab==='edit')body=`<form id="article-form" data-id="${id}">${field('title','Title',a.title)}${field('description','Meta description',a.description||'')}<div class="field"><label for="article-body">Article Markdown</label><textarea class="code" name="body" id="article-body">${esc(a.body||'')}</textarea></div><p class="hint">Edits invalidate the previous review. Run review again before publishing.</p>${formActions('Save changes')}</form>`;else if(tab==='sources')body=(a.sources||[]).map(s=>`<div class="source"><a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.url)}</a><p>${esc(typeof s.supports==='string'?s.supports:JSON.stringify(s.supports||''))}</p><small>${esc(s.url)}</small></div>`).join('')||'<p class="muted">Sources appear after research.</p>';else if(tab==='review')body=`<div class="notice ${a.review?.passed?'':'warning'}">${esc(a.review?.summary||'This article has not completed review.')}</div><h3>Editorial review</h3><ul class="detail-list">${(a.review?.issues||[]).map(s=>`<li>${esc(typeof s==='string'?s:JSON.stringify(s))}</li>`).join('')||'<li>No recorded issues.</li>'}</ul><h3 class="section">Publishing checks</h3><ul class="detail-list">${(a.checks?.issues||[]).map(s=>`<li>${esc(typeof s==='string'?s:JSON.stringify(s))}</li>`).join('')||'<li>No recorded issues.</li>'}</ul>${coverReview(a)}${a.publish_result?`<div class="notice section">${esc(a.publish_result.message||a.publish_result.status||'')}<br><span class="mono">${hosted?'':esc(a.publish_result.path||'')}</span>${a.publish_result.live_url?`<br><a href="${esc(safeURL(a.publish_result.live_url))}" target="_blank" rel="noopener noreferrer">View live article ↗</a>`:''}</div>`:''}`;else body=a.body?`<article class="article-preview">${coverPreview(a)}${markdown(a.body)}</article>`:`<div class="empty"><h2>${esc(a.title)}</h2><p>${esc(a.angle||'This article is planned and ready for research.')}</p><div class="muted">${esc(a.intent||'')} · ${esc(a.keyword||'')}</div></div>`;modal(a.title||'Article',`<div class="actions" style="margin-bottom:15px">${badge(a.status)}<span class="muted">${date(a.scheduled_at)}</span><a class="button small" href="/api/articles/${id}/download" download>Download article</a>${!hosted&&a.cover?.path?`<a class="button small" href="/api/articles/${id}/cover?download=1" download>Download cover</a>`:''}${!immutable&&['planned','error','held'].includes(a.status)?`<button class="button primary small" data-action="generate" data-id="${id}">Generate article</button>`:''}${a.body&&!immutable?`<button class="button small" data-action="review" data-id="${id}">Run review</button>`:''}${a.body&&!immutable?`<button class="button small" data-action="generate-cover" data-id="${id}" ${a.status==='generating_cover'?'disabled':''}>${a.cover?'Regenerate cover':'Generate cover'}</button>`:''}${['ready','exported','verification_pending','error'].includes(a.status)&&a.body?`<button class="button primary small" data-action="publish" data-id="${id}">Publish / export</button>`:''}${a.publish_result?.live_url?`<button class="button small" data-action="verify" data-id="${id}">Verify live page</button>`:''}<button class="button danger small" data-action="delete-article" data-id="${id}">Delete article</button></div>${a.error?`<div class="notice error">${esc(a.error)}</div>`:''}<div class="tabs">${(immutable?['preview','sources','review']:['preview','edit','sources','review']).map(t=>`<button class="tab ${t===tab?'active':''}" data-tab="${t}" data-id="${id}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${body}`,true);activeArticleDialog={id,tab,snapshot:JSON.stringify(a)};}
function connectionData(form){const d=Object.fromEntries(new FormData(form));for(const key of ['build_command','deploy_command']){try{d[key]=JSON.parse(d[key]||'[]');}catch{throw Error(`${label(key)} must be a JSON list, such as ["npm", "run", "build"].`);}if(!Array.isArray(d[key])||!d[key].every(x=>typeof x==='string'))throw Error(`${label(key)} must contain only strings.`);}d.auto_publish=form.auto_publish.checked;return d;}
async function mutation(path,method='POST',body={},message='Saved.'){await api(path,method,body);await refresh(true);toast(message);}
function userTouch(event){if(!authenticated||!event.isTrusted||!event.target?.closest?.('.app')||Date.now()-lastTouch<60000)return;lastTouch=Date.now();api('/api/auth/touch','POST',{}).catch(()=>{});}
document.addEventListener('pointerdown',userTouch);
document.addEventListener('keydown',userTouch);
document.addEventListener('click',async e=>{if(!authenticated)return;const el=e.target.closest('button,a');if(!el)return;try{if(el.dataset.clientTab){clientTab=el.dataset.clientTab;selected=el.dataset.id;view='client';history.replaceState(null,'','#client/'+selected+'/'+clientTab);render();return;}if(el.dataset.nav){navigate(el.dataset.nav);return;}if(el.dataset.client){navigate('client',el.dataset.client);return;}if(el.dataset.stage){articleFilter=articleFilter===el.dataset.stage?null:el.dataset.stage;render();return;}if(el.dataset.article){articleModal(el.dataset.article,el.dataset.openTab||'preview');return;}if(el.dataset.tab){articleModal(el.dataset.id,el.dataset.tab);return;}const action=el.dataset.action,id=el.dataset.id,c=client(id);if(!action)return;if(action==='passkey-remove'){if(credentialRows.length<=1)return;if(!window.confirm('Remove this passkey from RankMe?'))return;el.disabled=true;try{await RankMeAuth.removeCredential(id);credentialsLoaded=false;await loadCredentials();toast('Passkey removed.');}catch(error){if(authenticated)toast(RankMeAuth.errorMessage(error));}finally{el.disabled=false;}return;}if(action==='experiment-create')return experimentModal(c);if(action==='conversion-goal')return conversionGoalModal(c);if(action==='measurement-details')return measurementDetails(id);if(action==='visibility-task')return visibilityTask(id);if(action==='visibility-settings')return visibilitySettings(c);if(action==='opportunity-details')return visibilityOpportunity(id);if(hosted&&['google-setup','google-connect','google-disconnect','seo-properties','connection','test-connection','check-codex','vercel-link','vercel-check','vercel-unlink','vercel-disconnect','toggle-auto-publish','style-reference','brand-site'].includes(action))throw Error('Manage this connection in RankMe on your Mac.');if(action==='google-setup')return googleSetup();if(action==='cover-style')return coverStyleModal(c);if(action==='remove-client')return removeClientModal(c);if(action==='brand-site')return brandSiteModal(c);if(action==='color-add'){const rows=$('#color-rows');if(rows.children.length<6)rows.insertAdjacentHTML('beforeend',colorRow(''));return;}if(action==='color-remove'){el.closest('.color-row').remove();return;}if(action==='vercel-link')return vercelLinkModal(c);if(action==='seo-properties')return seoProperties(c);if(action==='backlink-open')return backlinkModal(id);if(action==='backlink-track')return modal('Track a known link',`<form id="backlink-track-form" data-id="${esc(id)}"><p class="muted">Enter the public page where a partner or publisher links to this client. RankMe saves it and checks the page.</p><div class="section">${field('source_url','Page containing the link','','url','Use the source page URL, not your client’s website.')}${field('notes','Notes (optional)','','textarea')}</div>${formActions('Save & check link')}</form>`);if(action==='add')return addModal();if(action==='close')return close();if(action==='refresh')return refresh(true);if(action==='profile')return profileModal(c);if(action==='subject')return subjectModal(c);if(action==='connection')return connectionModal(c);if(action==='schedule'){const local=c.next_run?new Date(new Date(c.next_run).getTime()-new Date(c.next_run).getTimezoneOffset()*60000).toISOString().slice(0,16):'';return modal('Set weekly schedule',`<form id="schedule-form" data-id="${id}">${field('next_run','Next article run',local,'datetime-local','Future runs follow every seven days.')}${formActions('Save schedule')}</form>`);}el.disabled=true;if(action==='experiment-cancel'){await mutation(`/api/experiments/${encodeURIComponent(id)}/cancel`,'POST',{},'Experiment tracking cancelled. Existing evidence is preserved.');}else if(action==='conversion-goal-clear'){await mutation(`/api/clients/${encodeURIComponent(id)}`,'PATCH',{conversion_goal:{}},'Conversion goal removed. Historical evidence is preserved.');close();}else if(action==='visibility-probe'){await mutation(`/api/clients/${encodeURIComponent(id)}/visibility-probe`,'POST',{},'Codex web answer sampling queued.');}else if(action==='visibility-research'){await mutation(`/api/clients/${encodeURIComponent(id)}/visibility-research`,'POST',{},'Visibility research queued.');}else if(action==='visibility-audit'){await mutation(`/api/clients/${encodeURIComponent(id)}/visibility-audit`,'POST',{},'Visibility audit queued.');}else if(action==='opportunity-execute'){await mutation(`/api/opportunities/${encodeURIComponent(id)}/execute`,'POST',{},'Draft action queued.');}else if(action==='opportunity-dismiss'||action==='opportunity-reopen'){await mutation(`/api/opportunities/${encodeURIComponent(id)}`,'PATCH',{status:action==='opportunity-dismiss'?'dismissed':'open'},action==='opportunity-dismiss'?'Opportunity dismissed.':'Opportunity reopened.');}else if(action==='google-connect'){const popup=window.open('about:blank','_blank');if(popup)popup.opener=null;try{const result=await api('/api/google/connect','POST',{});const url=new URL(result.url);if(url.protocol!=='https:'||url.hostname!=='accounts.google.com')throw Error('Google returned an unexpected sign-in address.');if(popup)popup.location.href=url.href;modal('Finish Google sign-in',`<p class="muted">Complete sign-in in the Google browser window, then return here. The connection status updates after Google confirms access.</p><a class="button primary section" href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">Open Google sign-in</a>`);}catch(error){if(popup)popup.close();throw error;}}else if(action==='stop-job'){await mutation(`/api/jobs/${encodeURIComponent(id)}/stop`,'POST',{},'Stopping. The article or website returns to where it was.');}else if(action==='dismiss-job'){await mutation(`/api/jobs/${encodeURIComponent(id)}/dismiss`,'POST',{},'Dismissed. The weekly schedule can continue.');}else if(action==='delete-article'){const a=state.articles.find(x=>x.id===id);const live=['published','refreshed','verification_pending'].includes(a?.status);if(!window.confirm(`Delete “${a?.title||'this article'}” from RankMe? Its draft, cover, and reviews are removed.${live?' The published page stays live on the website.':''} This cannot be undone.`))return;await api(`/api/articles/${encodeURIComponent(id)}/remove`,'POST',{});close();await refresh(true);toast('Article deleted.');}else if(action==='remove-cover'){if(!window.confirm('Delete this cover? The article needs a new cover before it can be published.'))return;await mutation(`/api/articles/${encodeURIComponent(id)}/remove-cover`,'POST',{},'Cover deleted. Generate a new one when ready.');if($('#modal').open)articleModal(id,'review');}else if(action==='style-reference'){const use=!!el.dataset.use;await mutation(`/api/articles/${encodeURIComponent(id)}/style-reference`,'POST',{use},use?'Added as a style reference. RankMe is learning the house style.':'Removed from style references.');if($('#modal').open)articleModal(id,'review');}else if(action==='vercel-disconnect'){if(!window.confirm('Disconnect Vercel from RankMe? Connected websites keep their settings but cannot track deployments until you reconnect.'))return;await mutation('/api/vercel/disconnect','POST',{},'Vercel disconnected.');}else if(action==='vercel-unlink'){if(!window.confirm(`Disconnect ${c?.name||'this website'} from its Vercel project? Nothing changes on Vercel or GitHub.`))return;await mutation(`/api/clients/${encodeURIComponent(id)}/vercel/unlink`,'POST',{},'Website disconnected from Vercel.');}else if(action==='vercel-check'){const text=el.textContent;el.textContent='Checking…';try{await mutation(`/api/clients/${encodeURIComponent(id)}/vercel/check`,'POST',{},'Website checked.');}finally{el.textContent=text;}}else if(action==='toggle-auto-publish'){const next=!c.connection?.auto_publish;if(next&&!window.confirm('Publish reviewed articles to the live website automatically, without waiting for you?'))return;await mutation(`/api/clients/${encodeURIComponent(id)}`,'PATCH',{connection:{auto_publish:next}},next?'Reviewed articles will publish automatically.':'Articles will wait for your approval.');}else if(action==='google-disconnect'){await mutation('/api/google/disconnect','POST',{},'Google disconnected. Saved reports remain local.');}else if(action==='seo-sync'){await mutation(`/api/clients/${id}/seo-sync`,'POST',{},'Google data sync queued.');}else if(action==='backlinks-discover'){await mutation(`/api/clients/${id}/backlinks-discover`,'POST',{},'Link opportunity research queued.');}else if(action==='backlink-check'){await mutation(`/api/backlinks/${id}/check`,'POST',{},'Link check started.');backlinkModal(id);}else if(action==='copy-draft'){await navigator.clipboard.writeText($('#backlink-draft').value);toast('Draft copied. No message sent.');}else if(action==='inspect')await mutation(`/api/clients/${id}/inspect`,'POST',{},'Inspection queued.');else if(action==='run')await mutation(`/api/clients/${id}/run`,'POST',{},'Next article queued.');else if(action==='toggle-client')await mutation(`/api/clients/${id}`,'PATCH',{automation:!c.automation},c.automation?'Client automation paused.':'Client automation enabled.');else if(action==='retry')await mutation(`/api/jobs/${id}/retry`,'POST',{},'Job queued again.');else if(action==='generate-cover'){await mutation(`/api/articles/${id}/cover`,'POST',{},'Cover generation and review queued.');articleModal(id);}else if(['generate','review','publish','verify'].includes(action)){const article=state.articles.find(a=>a.id===id),site=client(article?.client_id);if(action==='publish'&&!window.confirm(`Publish “${article?.title||'this article'}” to ${site?.name||site?.url||'the website'}?${site?.connection?.mode==='git'&&site?.connection?.auto_publish?' This pushes to the live site.':''}`))return;const inModal=$('#modal').open;await mutation(`/api/articles/${id}/${action}`,'POST',{},`${action[0].toUpperCase()+action.slice(1)} queued.`);if(inModal)articleModal(id);}else if(action==='check-codex')await mutation('/api/settings/check','POST',{},'Connection checked.');else if(action==='test-connection'){const result=await api('/api/connection/check','POST',connectionData($('#connection-form')));$('#connection-result').textContent=result.message||JSON.stringify(result);}}catch(error){if(error.queued){toast(error.message);if($('#modal').open)close();}else if($('#modal').open)$('#dialog-error').textContent=error.message;else toast(error.message);}finally{el.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='remove-confirm'){const typed=e.target.value.trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/$/,'');$('#remove-submit').disabled=typed!==e.target.dataset.expected;return;}const row=e.target.closest?.('.color-row');if(!row)return;const picker=row.querySelector('[data-color-picker]'),hex=row.querySelector('[data-color-hex]');if(e.target===picker)hex.value=picker.value.toUpperCase();else if(/^#[0-9a-fA-F]{6}$/.test(hex.value.trim()))picker.value=hex.value.trim();row.querySelector('.swatch').style.setProperty('--swatch',picker.value);});
